-- CompTIA Security+ (SY0-701) question bank. Written by Claude (claude-opus-5-5) to the
-- exam objectives, weighted like the real exam: General Security Concepts 12%, Threats,
-- Vulnerabilities & Mitigations 22%, Security Architecture 18%, Security Operations 28%,
-- Security Program Management & Oversight 20%.

-- CompTIA Security+ (SY0-701): 28 categories, one per exam objective.
insert into public.praxis_categories (exam, sort_order, slug, test_name, name, focus) values
  ('security-plus', 1, 'secplus-security-controls', 'Security+ · General Security Concepts', 'Security Controls', 'technical, managerial, operational, and physical controls; preventive, deterrent, detective, corrective, compensating, and directive control types'),
  ('security-plus', 2, 'secplus-security-concepts', 'Security+ · General Security Concepts', 'Fundamental Security Concepts', 'CIA, non-repudiation, AAA, gap analysis, zero trust, physical security, and deception technology'),
  ('security-plus', 3, 'secplus-change-management', 'Security+ · General Security Concepts', 'Change Management', 'approvals, ownership, impact analysis, backout plans, maintenance windows, and documentation'),
  ('security-plus', 4, 'secplus-cryptography', 'Security+ · General Security Concepts', 'Cryptographic Solutions', 'PKI, symmetric and asymmetric encryption, hashing, salting, key stretching, TPM/HSM, obfuscation, and certificates'),
  ('security-plus', 5, 'secplus-threat-actors', 'Security+ · Threats, Vulnerabilities & Mitigations', 'Threat Actors & Motivations', 'nation-states, unskilled attackers, hacktivists, insiders, organized crime, shadow IT, and their motivations'),
  ('security-plus', 6, 'secplus-threat-vectors', 'Security+ · Threats, Vulnerabilities & Mitigations', 'Threat Vectors & Attack Surfaces', 'message, file, voice, removable media, unsecure networks, supply chain, and social engineering'),
  ('security-plus', 7, 'secplus-vulnerabilities', 'Security+ · Threats, Vulnerabilities & Mitigations', 'Types of Vulnerabilities', 'application, OS, web, hardware, virtualization, cloud, supply chain, cryptographic, mobile, and zero-day'),
  ('security-plus', 8, 'secplus-malicious-activity', 'Security+ · Threats, Vulnerabilities & Mitigations', 'Indicators of Malicious Activity', 'malware, physical, network, application, cryptographic, and password attacks, and indicators of compromise'),
  ('security-plus', 9, 'secplus-mitigations', 'Security+ · Threats, Vulnerabilities & Mitigations', 'Mitigation Techniques', 'segmentation, access control, allow listing, isolation, patching, least privilege, and hardening'),
  ('security-plus', 10, 'secplus-architecture-models', 'Security+ · Security Architecture', 'Architecture Models', 'cloud responsibility, IaC, serverless, microservices, segmentation, containers, IoT, ICS/SCADA, and embedded systems'),
  ('security-plus', 11, 'secplus-secure-infrastructure', 'Security+ · Security Architecture', 'Securing Enterprise Infrastructure', 'device placement, security zones, failure modes, firewalls, IDS/IPS, 802.1X, VPNs, SD-WAN, and SASE'),
  ('security-plus', 12, 'secplus-data-protection', 'Security+ · Security Architecture', 'Data Protection', 'data types, classifications, states, sovereignty, and protection methods'),
  ('security-plus', 13, 'secplus-resilience-recovery', 'Security+ · Security Architecture', 'Resilience & Recovery', 'high availability, recovery sites, backups, replication, power, and continuity testing'),
  ('security-plus', 14, 'secplus-hardening', 'Security+ · Security Operations', 'Secure Baselines & Hardening', 'baselines, hardening targets, wireless and mobile security, and application security'),
  ('security-plus', 15, 'secplus-asset-management', 'Security+ · Security Operations', 'Asset Management', 'procurement, ownership, inventory, enumeration, and secure disposal'),
  ('security-plus', 16, 'secplus-vulnerability-management', 'Security+ · Security Operations', 'Vulnerability Management', 'scanning, threat intelligence, CVSS and CVE, prioritization, remediation, and validation'),
  ('security-plus', 17, 'secplus-monitoring', 'Security+ · Security Operations', 'Alerting & Monitoring', 'SIEM, log aggregation, SCAP, benchmarks, NetFlow, SNMP, DLP, and alert tuning'),
  ('security-plus', 18, 'secplus-enterprise-security', 'Security+ · Security Operations', 'Enterprise Security Capabilities', 'firewalls, IDS/IPS, web and DNS filtering, email security, FIM, NAC, EDR/XDR, and secure protocols'),
  ('security-plus', 19, 'secplus-identity-access', 'Security+ · Security Operations', 'Identity & Access Management', 'provisioning, SSO, federation, access control models, MFA, passwords, and privileged access'),
  ('security-plus', 20, 'secplus-automation', 'Security+ · Security Operations', 'Automation & Orchestration', 'provisioning, guardrails, ticketing, CI, APIs, and the benefits and risks of automation'),
  ('security-plus', 21, 'secplus-incident-response', 'Security+ · Security Operations', 'Incident Response', 'the incident response process, testing, root cause analysis, threat hunting, and digital forensics'),
  ('security-plus', 22, 'secplus-investigation-data', 'Security+ · Security Operations', 'Investigation Data Sources', 'firewall, application, endpoint, OS, IDS/IPS, and network logs, metadata, and packet captures'),
  ('security-plus', 23, 'secplus-governance', 'Security+ · Security Program Management & Oversight', 'Security Governance', 'policies, standards, procedures, governance structures, and data roles'),
  ('security-plus', 24, 'secplus-risk-management', 'Security+ · Security Program Management & Oversight', 'Risk Management', 'risk assessment and analysis, SLE/ALE/ARO, risk registers, strategies, and business impact analysis'),
  ('security-plus', 25, 'secplus-third-party-risk', 'Security+ · Security Program Management & Oversight', 'Third-Party Risk', 'vendor assessment and selection, agreement types, monitoring, and rules of engagement'),
  ('security-plus', 26, 'secplus-compliance', 'Security+ · Security Program Management & Oversight', 'Security Compliance', 'compliance reporting and monitoring, consequences of noncompliance, and privacy'),
  ('security-plus', 27, 'secplus-audits-assessments', 'Security+ · Security Program Management & Oversight', 'Audits & Assessments', 'attestation, internal and external audits, and penetration testing'),
  ('security-plus', 28, 'secplus-security-awareness', 'Security+ · Security Program Management & Oversight', 'Security Awareness', 'phishing campaigns, anomalous behavior, user training, and program reporting');

-- 526 questions, in rotation order (seq). Categories are interleaved so consecutive
-- days move between topics, and correct answers are spread evenly over A-D.
insert into public.daily_questions
  (exam, seq, category_id, question, choice_a, choice_b, choice_c, choice_d, correct_answer, explanation, model)
select 'security-plus', v.seq, c.id, v.question, v.a, v.b, v.c, v.d, v.correct, v.explanation, 'claude-opus-5-5'
from (values
  (1, 'secplus-malicious-activity', 'An attacker makes a web server fetch http://169.254.169.254/ to read cloud instance metadata and credentials. What attack is this?', 'Password spraying', 'Server-side request forgery (SSRF)', 'Cross-site request forgery (CSRF)', 'Reflected XSS', 'B', 'SSRF tricks the server into making requests on the attacker''s behalf, often reaching internal-only services. CSRF instead abuses the user''s browser.'),
  (2, 'secplus-secure-infrastructure', 'Which firewall type is designed specifically to protect web applications from attacks like SQL injection and XSS?', 'A web application firewall (WAF)', 'A network tap', 'A stateless packet filter', 'A layer 4 firewall', 'A', 'A WAF inspects HTTP and HTTPS at the application layer and understands web attack patterns. A layer 4 firewall only sees IP addresses and ports.'),
  (3, 'secplus-identity-access', 'Access is granted only if the user is in Finance, using a managed device, and connecting from the office during business hours. Which model is this?', 'Attribute-based access control (ABAC)', 'Mandatory access control', 'Role-based access control only', 'Discretionary access control', 'A', 'ABAC evaluates multiple attributes of the user, resource, and environment. It allows fine-grained, context-aware decisions.'),
  (4, 'secplus-cryptography', 'Which of the following is a symmetric encryption algorithm?', 'Diffie-Hellman', 'AES', 'ECC', 'RSA', 'B', 'AES uses the same key to encrypt and decrypt. RSA and ECC are asymmetric, and Diffie-Hellman is a key exchange method.'),
  (5, 'secplus-threat-vectors', 'Coordinated social media accounts spread false claims that a company''s product was hacked, intending to damage its reputation. What is this?', 'Disinformation', 'Whaling', 'Pretexting', 'Misinformation', 'A', 'Disinformation is deliberately false information spread to deceive. Misinformation is false information shared without intent to mislead.'),
  (6, 'secplus-vulnerabilities', 'Which type of vulnerability is hardest to defend against with patching alone?', 'A default password', 'A zero-day', 'A known vulnerability with a published patch', 'An open, unused port', 'B', 'By definition, no patch exists for a zero-day. Defense in depth and anomaly detection are needed until a fix is released.'),
  (7, 'secplus-architecture-models', 'What is a benefit of a centralized architecture compared with a decentralized one?', 'Each department controls its own security tools and policies independently', 'No single point of failure', 'Easier, consistent management and monitoring from one place', 'It removes the need for backups', 'C', 'Centralization simplifies policy enforcement and visibility. Its weakness is that the central point can become a single point of failure.'),
  (8, 'secplus-risk-management', 'Why is risk reporting to senior management important?', 'It replaces the need for technical controls', 'It''s only required after a reportable breach', 'It helps leadership understand and own key risks', 'It removes accepted risks from the register', 'C', 'Leadership must understand risks to set appetite and fund responses. Reporting creates accountability.'),
  (9, 'secplus-resilience-recovery', 'A full backup runs Sunday and differential backups run every other night. What is needed to restore on Thursday?', 'Sunday''s full backup and Wednesday night''s differential', 'Sunday''s full backup and Monday night''s differential', 'Every incremental backup since Sunday', 'Only Wednesday night''s differential', 'A', 'Each differential contains all changes since the last full backup, so only the full and the latest differential are needed. Incrementals would require every backup in the chain.'),
  (10, 'secplus-enterprise-security', 'Which port does RDP use by default, and why shouldn''t it be exposed directly to the internet?', '25; it''s used for email relaying', '22; it conflicts with SSH', '3389; exposed RDP is often brute-forced', '443; it shares the HTTPS port', 'C', 'Exposed RDP is a common ransomware entry point. It should sit behind a VPN or gateway with MFA.'),
  (11, 'secplus-data-protection', 'Which statement about data in transit is correct?', 'It is always safe on internal networks', 'It can be protected only by hashing', 'It doesn''t need protection if it''s at rest elsewhere', 'It should be protected with encryption such as TLS or IPsec', 'D', 'Data moving across any network can be intercepted, including internal networks. Encrypting it in transit prevents eavesdropping.'),
  (12, 'secplus-hardening', 'An enterprise wants each employee to authenticate to Wi-Fi with their own credentials instead of a shared password. What should it use?', 'WEP with a 128-bit key', 'WPA3-Personal with a shared passphrase', 'An open network with a captive portal', 'WPA3-Enterprise with 802.1X and a RADIUS server', 'D', 'Enterprise mode authenticates each user through 802.1X and RADIUS, which allows individual accountability and revocation. A shared passphrase must be changed for everyone when one person leaves.'),
  (13, 'secplus-incident-response', 'What should a forensic report include?', 'The company''s financial statements', 'Employee records unrelated to the case', 'The investigator''s personal opinions only', 'The evidence, methods, findings, and timeline', 'D', 'Reports must be accurate and repeatable for management and legal use. They document what was found and how.'),
  (14, 'secplus-threat-actors', 'What makes advanced persistent threats (APTs) especially dangerous?', 'They maintain stealthy, long-term access and adapt to defenses', 'They attack only once, then leave', 'They always announce themselves with ransom notes after the first intrusion', 'They rely only on publicly available scripts', 'A', 'APTs, often linked to nation-states, aim to remain undetected for months to keep gathering data. Ransom notes are typical of financially motivated criminals.'),
  (15, 'secplus-mitigations', 'Why is continuous monitoring considered a mitigation technique?', 'It shortens the time to detect and respond to threats', 'It encrypts data as it is collected', 'It prevents attacks from starting by blocking them at the perimeter', 'It removes the need for regular patching', 'A', 'Monitoring shortens the time attackers go unnoticed. It complements, but doesn''t replace, preventive controls like patching.'),
  (16, 'secplus-vulnerability-management', 'Why is a false negative in vulnerability scanning dangerous?', 'The scan reports duplicate findings', 'Analysts waste time on issues that don''t exist', 'A real vulnerability goes unreported and unfixed', 'The scanner crashes the systems it scans', 'C', 'False negatives create a false sense of security. Using credentialed scans and multiple tools reduces them.'),
  (17, 'secplus-monitoring', 'What is the purpose of time synchronization (NTP) across all monitored systems?', 'To encrypt logs before they''re sent to the SIEM', 'To assign IP addresses to new hosts on boot', 'To speed up authentication traffic on the network', 'So timestamps can be correlated during investigations', 'D', 'If clocks differ, reconstructing a timeline across systems becomes unreliable. Consistent time is essential for correlation.'),
  (18, 'secplus-governance', 'Which policy describes how an organization keeps critical business functions running during a disruption?', 'Clean desk policy', 'Acceptable use policy', 'Business continuity policy', 'Password policy', 'C', 'Business continuity covers maintaining operations during and after disruptions. Disaster recovery focuses specifically on restoring IT systems.'),
  (19, 'secplus-audits-assessments', 'Testers are given limited information, such as a list of IP ranges and a standard user account. What test type is this?', 'Partially known environment (gray box)', 'Unknown environment (black box)', 'Known environment (white box)', 'Physical penetration test', 'A', 'Gray box testing balances realism and efficiency with partial knowledge. It''s common because it saves discovery time.'),
  (20, 'secplus-security-concepts', 'In the AAA framework, which component records what a user did after logging in?', 'Authorization', 'Accounting', 'Authentication', 'Attestation', 'B', 'Accounting tracks user activity, such as logins, commands, and resources accessed. Authentication proves identity, and authorization decides what the user may do.'),
  (21, 'secplus-security-controls', 'Which is the BEST example of a physical control?', 'Data loss prevention software on endpoints', 'Bollards outside the building entrance', 'A clean desk policy for all staff', 'Monthly vulnerability scans of servers', 'B', 'Bollards are tangible barriers that protect the facility. DLP and scanning are technical controls, and a clean desk policy is a directive, managerial control.'),
  (22, 'secplus-third-party-risk', 'Which document defines the specific tasks, deliverables, and timeline for one project under a larger contract?', 'Memorandum of understanding', 'Master service agreement', 'Statement of work (work order)', 'Business partners agreement', 'C', 'A SOW details what will be done for a particular engagement. It works under the terms of the MSA.'),
  (23, 'secplus-compliance', 'What is the difference between internal and external compliance monitoring?', 'Internal monitoring is never required if external audits are done', 'External monitoring is done by employees', 'They are the same process', 'Internal is done by staff; external by independent parties', 'D', 'Internal monitoring catches issues early, and external monitoring provides independent assurance. Both are valuable.'),
  (24, 'secplus-change-management', 'Which group commonly reviews and approves significant changes in an organization?', 'The change advisory board', 'The incident response team', 'The red team', 'The help desk', 'A', 'The change advisory board (CAB) evaluates risk, impact, and timing before approving changes. The red team performs offensive testing and has no role in approvals.'),
  (25, 'secplus-investigation-data', 'What is metadata in the context of an investigation?', 'The rules in a firewall''s rule base', 'Data about data, like headers and timestamps', 'The body text of an email message', 'The encrypted contents of a file recovered from a disk image', 'B', 'Metadata can reveal who created or sent something and when. Email headers can trace a phishing message''s true origin.'),
  (26, 'secplus-asset-management', 'Which practice best tracks laptops as they are issued to and returned by employees?', 'Recording only each device''s purchase date', 'Removing asset tags so stolen devices are harder to resell', 'Letting employees track devices informally', 'Recording the assigned user in the asset inventory', 'D', 'Tracking who holds each asset supports accountability and recovery. It also ensures devices are collected and wiped when employees leave.'),
  (27, 'secplus-automation', 'In cloud environments, automated guardrails are used to:', 'Speed up connections between regions', 'Disable logging to reduce cloud costs', 'Block or fix deployments that violate policy', 'Grant public access to new resources so teams can work faster', 'C', 'Guardrails automatically block or fix noncompliant configurations, such as public storage. They enforce baselines at scale.'),
  (28, 'secplus-security-awareness', 'Which topic is especially important in training for employees working remotely or in hybrid arrangements?', 'Booking conference rooms securely', 'Data center fire suppression systems', 'Badge and sign-in procedures for visitors at the front desk', 'Securing home networks and avoiding public Wi-Fi', 'D', 'Remote work moves company data onto home networks and personal spaces. Training covers VPN use, Wi-Fi security, and physical privacy.'),
  (29, 'secplus-malicious-activity', 'An attacker sends small DNS queries with a spoofed source address so that large responses flood the victim. What type of attack is this?', 'A reflected, amplified DDoS attack', 'A credential replay attack', 'An on-path attack', 'A DNS cache poisoning attack', 'A', 'Amplification turns small requests into large responses, and spoofing reflects them at the victim. Open DNS resolvers are a common amplifier.'),
  (30, 'secplus-secure-infrastructure', 'A switch is configured to allow only one specific MAC address on each office port. What is this feature?', 'VLAN hopping', 'Link aggregation', 'Port security', 'Spanning tree', 'C', 'Port security limits which MAC addresses can use a port, blocking unauthorized devices. MAC addresses can be spoofed, though, so 802.1X is stronger.'),
  (31, 'secplus-identity-access', 'Which XML-based standard is commonly used to exchange authentication data between an identity provider and a web application for SSO?', 'OAuth', 'Kerberos', 'LDAP', 'SAML', 'D', 'SAML passes signed assertions from an identity provider to a service provider. OAuth is mainly for authorization.'),
  (32, 'secplus-cryptography', 'Adding a unique random value to each password before hashing, so identical passwords produce different hashes, is called:', 'Salting', 'Tokenization', 'Key stretching', 'Steganography', 'A', 'A salt makes each hash unique, which defeats precomputed rainbow tables. Key stretching instead slows down each guess by hashing many times.'),
  (33, 'secplus-threat-vectors', 'An attacker registers examp1e.com, hoping users who mistype example.com will land on a malicious site. This is:', 'Brand impersonation', 'DNS poisoning', 'Typosquatting', 'Pharming', 'C', 'Typosquatting, or URL hijacking, registers domains that look like common misspellings of real ones. DNS poisoning instead corrupts name resolution for the real domain.'),
  (34, 'secplus-vulnerabilities', 'A hardware supplier ships network cards with a backdoor in the firmware. Which category of risk does this represent?', 'Race condition', 'Hardware supply chain', 'Social engineering', 'Misconfiguration', 'B', 'Compromised components from a hardware provider are a supply chain risk. Buying from trusted vendors and verifying hardware integrity helps reduce it.'),
  (35, 'secplus-architecture-models', 'An organization defines its servers, networks, and firewall rules in version-controlled template files that build identical environments automatically. What is this?', 'Serverless computing', 'Software-defined networking', 'Infrastructure as code', 'Air gapping', 'C', 'Infrastructure as code (IaC) provisions infrastructure from templates, which makes deployments repeatable and reviewable. It also reduces configuration drift caused by manual changes.'),
  (36, 'secplus-risk-management', 'An organization performs risk assessments continuously using automated tools that update in real time. Which assessment frequency is this?', 'Ad hoc', 'Recurring annually', 'Continuous', 'One-time', 'C', 'Continuous assessment monitors risk as conditions change. Recurring assessments happen on a set schedule, such as annually.'),
  (37, 'secplus-resilience-recovery', 'Why do organizations use platform diversity, such as different operating systems or vendors, for critical systems?', 'Because single-vendor systems can''t be secured', 'To make patch management simpler', 'To reduce the amount of staff training needed', 'So one flaw or failure can''t affect every system', 'D', 'Diversity limits the impact of one vendor''s flaw or outage. It comes at the cost of more complex management.'),
  (38, 'secplus-enterprise-security', 'A tool alerts whenever critical system files are changed unexpectedly. What is it?', 'File integrity monitoring (FIM)', 'Network access control (NAC)', 'A secure web gateway (SWG)', 'Data loss prevention (DLP)', 'A', 'FIM compares files against known-good hashes and alerts on changes. It can detect rootkits and unauthorized modifications.'),
  (39, 'secplus-data-protection', 'Which method converts data to a fixed-length value that can''t be reversed, making it useful for verifying data without storing it?', 'Masking', 'Encryption', 'Tokenization', 'Hashing', 'D', 'Hashing is one-way, so the original can''t be recovered. Encryption is reversible with the key.'),
  (40, 'secplus-hardening', 'A developer''s code is checked for security flaws by a tool that analyzes the source without running it. What is this?', 'Penetration testing', 'Fuzzing', 'Static code analysis', 'Dynamic analysis', 'C', 'Static analysis (SAST) examines source code for flaws early in development. Dynamic analysis tests the application while it''s running.'),
  (41, 'secplus-incident-response', 'The team removes malware, deletes attacker accounts, and patches the exploited vulnerability. Which phase is this?', 'Containment', 'Lessons learned', 'Detection', 'Eradication', 'D', 'Eradication eliminates the threat and its root cause. Recovery then restores systems to normal operation.'),
  (42, 'secplus-threat-actors', 'A security researcher finds a flaw, reports it privately to the vendor, and gives them time to patch before disclosing. What is the researcher''s motivation?', 'Ethical', 'War', 'Revenge', 'Financial extortion', 'A', 'Ethical, or authorized, hacking aims to improve security through responsible disclosure. Extortion would mean demanding payment to keep quiet.'),
  (43, 'secplus-mitigations', 'An endpoint detection and response (EDR) agent is installed on every workstation. Which hardening step does this represent?', 'Changing default passwords', 'Installing endpoint protection', 'Disabling ports', 'Decommissioning', 'B', 'Endpoint protection such as EDR or antivirus detects and blocks malicious activity on hosts. It''s a standard hardening step for every endpoint.'),
  (44, 'secplus-vulnerability-management', 'Instead of fixing a low-risk vulnerability, management decides to buy cyber insurance to cover possible losses. What response is this?', 'Risk transference', 'Risk mitigation', 'Risk acceptance', 'Risk avoidance', 'A', 'Insurance transfers the financial impact to a third party. The vulnerability still exists, so the decision should be documented.'),
  (45, 'secplus-monitoring', 'A SIEM generates so many false alerts that analysts start ignoring them. What should be done?', 'Tune the alert rules', 'Disable the SIEM until it''s fixed', 'Stop forwarding logs from servers', 'Raise all alerts to critical', 'A', 'Alert tuning adjusts thresholds and rules so real threats stand out. Alert fatigue causes real incidents to be missed.'),
  (46, 'secplus-governance', 'Step-by-step instructions for onboarding a new employee, including account creation and badge issuance, are an example of a:', 'Procedure', 'Guideline', 'Policy', 'Standard', 'A', 'Procedures describe exactly how to perform a task. They make sure processes are done consistently and securely.'),
  (47, 'secplus-audits-assessments', 'A department uses a checklist to evaluate its own compliance with security policies. What is this?', 'A penetration test', 'A regulatory examination', 'A self-assessment', 'An independent third-party audit', 'C', 'Self-assessments are internal reviews that find gaps early. They''re less independent than external audits.'),
  (48, 'secplus-malicious-activity', 'An attacker uses a handheld device to copy the data from an employee''s proximity badge and creates a duplicate. What is this?', 'Tailgating', 'Shoulder surfing', 'Bluejacking', 'RFID cloning', 'D', 'RFID cloning copies the badge''s credential so the attacker can use it. Encrypted smart cards and requiring a PIN help prevent it.'),
  (49, 'secplus-secure-infrastructure', 'A reverse proxy placed in front of a company''s web servers primarily:', 'Caches DNS lookups for the internal network', 'Accepts client requests for the servers and hides them', 'Assigns IP addresses to internal clients', 'Filters employees'' outbound web browsing and caches popular pages', 'B', 'A reverse proxy accepts incoming requests and forwards them to back-end servers, hiding their details. It''s often combined with load balancing and WAF features.'),
  (50, 'secplus-security-concepts', 'A security team compares its current controls against the NIST Cybersecurity Framework to find missing safeguards. What is this?', 'A tabletop exercise', 'A penetration test', 'A business impact analysis', 'A gap analysis', 'D', 'A gap analysis compares the current state to a desired standard to find shortfalls. A penetration test actively exploits weaknesses rather than comparing against a framework.'),
  (51, 'secplus-identity-access', 'Managers periodically review and confirm that their team members'' access rights are still appropriate. What is this called?', 'Federation', 'Tokenization', 'Identity proofing', 'Attestation (access recertification)', 'D', 'Access attestation catches permission creep and leftover access. Many regulations require it.'),
  (52, 'secplus-cryptography', 'What serves as the root of trust in a public key infrastructure?', 'The certificate revocation list published by the CA', 'The intermediate CA that issued the server''s certificate', 'The server''s certificate signing request', 'The root CA''s self-signed certificate', 'D', 'Trust flows down from the root CA through intermediate CAs to end-entity certificates. If the root is trusted, certificates that chain to it can be validated.'),
  (53, 'secplus-threat-vectors', 'What is the key difference between client-based and agentless vulnerable software?', 'Agentless software always runs with full administrator rights on the host', 'Agentless software must be loaded from removable media on each host', 'Client-based installs software on the endpoint; agentless runs remotely', 'Client-based software is patched centrally and never needs host updates', 'C', 'Installed clients expand the endpoint''s attack surface and need patching. Agentless tools reduce local risk but rely on remote access and services.'),
  (54, 'secplus-vulnerabilities', 'An operating system flaw lets a standard user run code with administrator rights. What type of vulnerability is this?', 'Watering hole', 'OS-based privilege escalation', 'Data masking', 'Typosquatting', 'B', 'OS vulnerabilities that allow privilege escalation give attackers full control of the system. Timely OS patching is the main defense.'),
  (55, 'secplus-architecture-models', 'An application is built as many small, independent services that communicate through APIs. What is a key security consideration?', 'Each API between services must be authenticated and secured', 'A single compromise always takes down the whole application', 'There is only one component to patch', 'APIs never need input validation', 'A', 'Microservices increase the number of API endpoints, so service-to-service authentication and authorization are essential. Their independence can also limit the blast radius of a compromise.'),
  (56, 'secplus-risk-management', 'A business can tolerate losing no more than one hour of transaction data. Which metric does this define?', 'Recovery point objective (RPO)', 'Recovery time objective (RTO)', 'Single loss expectancy (SLE)', 'Mean time to repair (MTTR)', 'A', 'RPO drives backup frequency; here, backups or replication at least every hour. RTO is about downtime, not data loss.'),
  (57, 'secplus-security-controls', 'Antivirus software finds a malicious file and moves it into quarantine. Which control type is the quarantine action?', 'Deterrent', 'Directive', 'Compensating', 'Corrective', 'D', 'Quarantining limits the damage of a threat that has already been found, which is corrective. Finding the file was detective, but moving it out of harm''s way corrects the situation.'),
  (58, 'secplus-third-party-risk', 'Which agreement describes the relationship between two business partners, including each party''s responsibilities and profit sharing?', 'Service level agreement (SLA)', 'Memorandum of understanding (MOU)', 'Non-disclosure agreement (NDA)', 'Business partners agreement (BPA)', 'D', 'A BPA covers how partners work together, share responsibilities, and divide profits. It often includes security obligations.'),
  (59, 'secplus-compliance', 'What does due care mean in a compliance context?', 'Ignoring risks that are costly to fix', 'Doing the minimum required once', 'Delegating all duties to vendors', 'Taking reasonable steps to protect assets', 'D', 'Due care is acting responsibly to protect assets, while due diligence is investigating and understanding risks. Both help show reasonable security.'),
  (60, 'secplus-resilience-recovery', 'Why should backups be encrypted?', 'To make nightly backup jobs complete faster over the network', 'To reduce the storage space required', 'To remove the need to test restores', 'To protect the data if backup media is stolen', 'D', 'Backups contain copies of sensitive data and need the same protection as production. The keys must be managed so restores remain possible.'),
  (61, 'secplus-enterprise-security', 'An email security gateway helps protect an organization by:', 'Filtering spam, phishing, and malicious attachments', 'Blocking malicious DNS lookups from browsers', 'Assigning IP addresses to internal mail servers', 'Encrypting files stored on user laptops', 'A', 'Email gateways scan inbound and outbound mail for threats and policy violations. Email remains the top delivery method for malware and phishing.'),
  (62, 'secplus-change-management', 'After a change is implemented, which activity ensures diagrams and procedures reflect the new environment?', 'Performing a gap analysis', 'Rotating encryption keys', 'Running a tabletop exercise', 'Updating documentation', 'D', 'Change management includes updating diagrams, policies, and procedures so they stay accurate. Outdated documentation slows troubleshooting and incident response.'),
  (63, 'secplus-malicious-activity', 'Many users suddenly report their accounts are locked out, though they haven''t attempted to log in. What is this most likely an indicator of?', 'Normal password expiration', 'A failed group policy update', 'A brute-force or password-guessing attack', 'An expired directory certificate', 'C', 'Unexpected lockouts usually mean someone is guessing passwords against those accounts. The authentication logs will show the source of the attempts.'),
  (64, 'secplus-secure-infrastructure', 'Which architecture combines SD-WAN with cloud-delivered security services such as secure web gateways, CASB, and zero trust network access?', 'Unified threat management (UTM)', 'Secure Access Service Edge (SASE)', 'Network access control (NAC)', 'A screened subnet (DMZ)', 'B', 'SASE delivers networking and security from the cloud, close to users wherever they are. UTM is a single on-premises appliance.'),
  (65, 'secplus-data-protection', 'Which data type includes contracts, court records, and documents related to litigation?', 'Non-human-readable data', 'Financial data', 'Legal data', 'Public data', 'C', 'Legal data often has retention requirements and may be subject to legal holds. It must be protected and preserved properly.'),
  (66, 'secplus-hardening', 'Employees use their own phones for work, and the company manages a separate work container on them. What deployment model is this?', 'CYOD', 'BYOD', 'COPE', 'Corporate-owned only', 'B', 'Bring your own device means personal devices are used for work, often with containerization to separate corporate data. COPE devices are company-owned.'),
  (67, 'secplus-incident-response', 'Systems are restored from clean backups and monitored closely as they return to production. Which phase is this?', 'Preparation', 'Recovery', 'Analysis', 'Eradication', 'B', 'Recovery brings systems back to normal and verifies they''re clean. Extra monitoring watches for signs the attacker returns.'),
  (68, 'secplus-investigation-data', 'During an investigation, which log would show that a connection from an external IP to an internal server on port 3389 was allowed?', 'Firewall logs', 'Application logs', 'DHCP logs only', 'Print server logs', 'A', 'Firewall logs record allowed and denied connections with addresses and ports. They show which traffic crossed network boundaries.'),
  (69, 'secplus-identity-access', 'Which type of authenticator is most resistant to phishing?', 'A one-time code sent by email', 'A FIDO2 hardware security key', 'An SMS one-time passcode', 'A knowledge-based security question', 'B', 'FIDO2 keys use cryptography bound to the legitimate site, so a fake site can''t use the response. SMS codes can be phished or intercepted through SIM swapping.'),
  (70, 'secplus-threat-actors', 'Which threat actor typically has the most resources and sophistication?', 'Unskilled attacker', 'Nation-state', 'Hacktivist', 'Shadow IT', 'B', 'Nation-states can fund large teams, develop custom malware, and buy or discover zero-day exploits. Unskilled attackers have the least capability.'),
  (71, 'secplus-mitigations', 'What does encryption mitigate when a laptop containing customer data is stolen?', 'Malware already running on the laptop', 'The physical theft of the device', 'Loss of the data if the laptop was never backed up', 'Unauthorized access to the data on the drive', 'D', 'Encryption makes the data unreadable without the key, so a stolen device doesn''t become a data breach. It doesn''t stop the theft.'),
  (72, 'secplus-vulnerability-management', 'Why is a vulnerability report shared with management after scanning?', 'To assign blame for unpatched systems', 'To communicate risk and track remediation progress', 'To replace the need for remediation', 'To satisfy a requirement with no business value', 'B', 'Reporting turns scan results into business decisions and accountability. Metrics show whether remediation is keeping pace.'),
  (73, 'secplus-monitoring', 'What is SCAP used for?', 'Automating configuration and vulnerability checks with standard formats', 'Correlating logs from many different sources in real time', 'Encrypting email between mail servers', 'Capturing wireless packets for analysis', 'A', 'The Security Content Automation Protocol standardizes how tools check configurations and vulnerabilities. It makes results consistent across products.'),
  (74, 'secplus-governance', 'A security team follows a predefined, step-by-step guide for responding to a phishing incident. What is this guide called?', 'A playbook', 'A risk register', 'An acceptable use policy', 'A service level agreement', 'A', 'Playbooks detail response steps for specific scenarios, and they can be manual or automated with SOAR. They speed up and standardize response.'),
  (75, 'secplus-audits-assessments', 'Why must penetration testers have written authorization before testing?', 'Testing without permission is illegal', 'It''s only required for physical tests', 'Authorization makes the test run faster', 'It replaces the rules of engagement', 'A', 'Written permission legally separates a test from an attack. It also defines scope and protects both parties.'),
  (76, 'secplus-cryptography', 'Why do browsers display warnings for self-signed certificates on public websites?', 'They always use weaker encryption algorithms', 'They don''t include the server''s public key', 'They can''t be used for TLS connections', 'They aren''t issued by a CA the browser trusts', 'D', 'Browsers trust certificates that chain to a known root CA. A self-signed certificate can use strong cryptography, but nothing vouches for the owner''s identity.'),
  (77, 'secplus-threat-vectors', 'The accounts payable team receives an email that appears to come from the CFO''s real mailbox, instructing them to wire funds to a new vendor account. What attack is most likely?', 'Smishing', 'Watering hole', 'Bluejacking', 'Business email compromise', 'D', 'Business email compromise uses a compromised or spoofed executive or vendor account to trick staff into fraudulent payments. Verifying payment changes out of band is the key defense.'),
  (78, 'secplus-vulnerabilities', 'A program copies user input into a fixed-size memory area without checking its length, letting an attacker overwrite adjacent memory. What vulnerability is this?', 'SQL injection', 'Race condition', 'Buffer overflow', 'Cross-site scripting', 'C', 'A buffer overflow writes past the end of an allocated buffer, which can crash the program or run attacker code. Input length validation and memory-safe languages help prevent it.'),
  (79, 'secplus-architecture-models', 'What is the primary security concern with industrial control systems (ICS) and SCADA?', 'They rely entirely on public cloud services that can''t be secured by the owner', 'They use encryption too strong to be inspected', 'They store large amounts of personal customer data', 'They often run legacy, hard-to-patch systems controlling physical processes', 'D', 'ICS and SCADA control physical equipment, so attacks can cause physical harm. Many run old software that can''t be easily patched, so isolation is critical.'),
  (80, 'secplus-risk-management', 'Which metric defines the maximum acceptable time to restore a system after a disruption?', 'Recovery point objective (RPO)', 'Annualized rate of occurrence (ARO)', 'Recovery time objective (RTO)', 'Mean time between failures (MTBF)', 'C', 'RTO is how quickly a system must be back. RPO is how much data loss, measured in time, is acceptable.'),
  (81, 'secplus-asset-management', 'Assigning a data classification to an asset helps determine:', 'Which vendor is responsible for repairs', 'The security controls and handling it requires', 'Its depreciation schedule and purchase price', 'Its required network bandwidth', 'B', 'Classification drives protection levels, such as encryption, access restrictions, and disposal methods. More sensitive assets need stronger controls.'),
  (82, 'secplus-automation', 'A SOAR playbook automatically opens a ticket and escalates to the on-call analyst when a critical alert fires. What benefit does this provide?', 'Increased technical debt with no benefit', 'Elimination of all false positives', 'Faster, consistent reaction time', 'No need for any analysts', 'C', 'Automating ticket creation and escalation speeds response and ensures alerts aren''t missed. Analysts still handle the investigation.'),
  (83, 'secplus-security-awareness', 'Why should security awareness training be recurring rather than one-time?', 'Threats evolve, and reinforcement keeps habits strong', 'One-time training is prohibited by most regulations', 'People can''t retain anything from one session', 'Training certificates legally expire after one day', 'A', 'Periodic training and refreshers adapt to new threats and keep habits strong. Initial onboarding training alone fades over time.'),
  (84, 'secplus-security-concepts', 'A DDoS attack makes a company''s website unreachable. Which security goal is primarily affected?', 'Confidentiality', 'Integrity', 'Availability', 'Non-repudiation', 'C', 'A denial-of-service attack keeps legitimate users from reaching the service, which is a loss of availability. No data is necessarily exposed or altered.'),
  (85, 'secplus-resilience-recovery', 'A company runs its new recovery system alongside the primary system with the same inputs, comparing the results without disrupting operations. What testing method is this?', 'A full interruption test', 'A tabletop exercise', 'A cold site test', 'Parallel processing', 'D', 'Parallel processing runs both systems at once to validate the recovery environment. Operations continue on the primary system during the test.'),
  (86, 'secplus-enterprise-security', 'What is an advantage of anomaly-based intrusion detection?', 'It doesn''t need any baseline of normal network traffic to work', 'It never produces false positives', 'It can detect new attacks that differ from normal behavior', 'It relies on a database of known signatures', 'C', 'Anomaly detection can catch zero-days by spotting unusual activity. It needs a good baseline and can produce more false positives.'),
  (87, 'secplus-malicious-activity', 'A file server''s CPU stays at 100 percent and outbound traffic spikes at 2 a.m. every night. Which indicator is this?', 'Account lockout', 'Unusual resource consumption', 'Blocked content', 'Impossible travel', 'B', 'Unexplained resource use can signal cryptomining, data exfiltration, or other malicious activity. Establishing a normal baseline makes anomalies like this stand out.'),
  (88, 'secplus-secure-infrastructure', 'A security team needs to copy network traffic to a monitoring tool without affecting the live connection. Which device fits best?', 'A load balancer', 'A router', 'A network tap', 'An inline IPS', 'C', 'A tap passively copies traffic to a monitor, so it can''t disrupt the connection. An inline IPS sits in the path and could block or delay traffic.'),
  (89, 'secplus-identity-access', 'What security benefit does a password manager provide?', 'It shares passwords with coworkers automatically', 'It stores passwords in plaintext for convenience', 'It eliminates the need for MFA on accounts it stores passwords for', 'It lets users keep unique, strong passwords for every account', 'D', 'Password managers generate and store unique passwords, preventing reuse. They should be protected with a strong master password and MFA.'),
  (90, 'secplus-data-protection', 'A file is being processed in RAM by an application. Which data state is this?', 'Data in use', 'Data in transit', 'Archived data', 'Data at rest', 'A', 'Data in use is actively being processed and is often unencrypted in memory. Secure enclaves can help protect it.'),
  (91, 'secplus-hardening', 'A visual map showing wireless signal strength across a floor plan is called a:', 'Heat map', 'Data flow diagram', 'Risk matrix', 'Network diagram', 'A', 'Heat maps show coverage strengths and dead zones from a site survey. They help place access points to provide coverage without excessive leakage.'),
  (92, 'secplus-incident-response', 'During containment of a fast-spreading worm, why might a team isolate an entire network segment instead of individual hosts?', 'To skip the eradication phase', 'To make file transfers faster', 'To contain the spread when many hosts may be infected', 'Because isolating individual hosts is never allowed during containment', 'C', 'Segment isolation can contain an outbreak faster than chasing hosts one by one. It trades some business impact for speed.'),
  (93, 'secplus-security-controls', 'An access control vestibule at a data center entrance is primarily what kind of control?', 'Technical and detective', 'Physical and preventive', 'Managerial and directive', 'Operational and corrective', 'B', 'A vestibule (mantrap) physically stops unauthorized people, including tailgaters, from entering. It''s a physical barrier that prevents access rather than detecting it after the fact.'),
  (94, 'secplus-third-party-risk', 'What do rules of engagement define for a third-party penetration test?', 'Scope, timing, allowed techniques, and contacts', 'The vendor''s pricing and payment terms', 'The company''s data retention schedule', 'The testers'' certifications, resumes, and hourly billing rates', 'A', 'Rules of engagement keep testing authorized and safe. Testing outside the agreed scope could be illegal or disruptive.'),
  (95, 'secplus-compliance', 'Under privacy law, what does data ownership mean for personal data?', 'The organization is accountable for the personal data it collects', 'Data belongs to the employee who entered it', 'Customers give up all rights to data once they hand it over', 'Ownership applies only to paper records', 'A', 'Organizations are accountable for personal data they hold, while individuals keep rights over it. Clear ownership supports compliance.'),
  (96, 'secplus-cryptography', 'Alice wants to send Bob a message that only Bob can read. Which key does she use to encrypt it?', 'Bob''s public key', 'Alice''s private key', 'Alice''s public key', 'Bob''s private key', 'A', 'Anything encrypted with Bob''s public key can be decrypted only with Bob''s private key, which only he holds. Encrypting with Alice''s private key would create a signature, not confidentiality.'),
  (97, 'secplus-threat-vectors', 'A port scan shows Telnet, FTP, and SMB open on an internet-facing server that only needs to serve HTTPS. Which threat vector does this represent?', 'Supply chain', 'Removable devices', 'Open service ports', 'Bluetooth', 'C', 'Every unnecessary open port is an extra attack surface. Only HTTPS should be exposed; the other services should be disabled or blocked.'),
  (98, 'secplus-vulnerabilities', 'An attacker tricks a fake update server into delivering a malicious package that the application installs without checking its signature. What vulnerability made this possible?', 'VM escape through a flaw in the hypervisor''s update service', 'A race condition between check and use', 'Malicious update due to missing integrity validation', 'Directory traversal in the update path', 'C', 'Updates should be digitally signed and verified before installation. Without that check, an attacker who controls the update path can push malware.'),
  (99, 'secplus-architecture-models', 'Why is code scanning important for infrastructure as code templates?', 'Templates must be rewritten for each deployment', 'A template misconfiguration is copied to every deployment', 'IaC tools disable cloud logging by default', 'Templates are encrypted and can''t be read by people', 'B', 'IaC makes deployment consistent, including consistently wrong settings. Scanning templates catches issues like open ports or hard-coded secrets before deployment.'),
  (100, 'secplus-risk-management', 'What is a risk threshold?', 'The number of controls currently in place', 'The level at which action or escalation is required', 'The total value of all assets in scope', 'The maximum throughput of the firewall', 'B', 'Thresholds define when a risk must be escalated or treated. They put risk tolerance into practice.'),
  (101, 'secplus-threat-actors', 'An attacker floods an online gaming service with traffic just to watch it go down, without demanding anything. What is the most likely motivation?', 'Disruption or chaos', 'Espionage', 'Blackmail', 'Data exfiltration', 'A', 'With no demands and no data theft, the goal appears to be disruption for its own sake. Blackmail would involve a demand.'),
  (102, 'secplus-mitigations', 'A suspicious executable needs to be analyzed without risking the production network. Which mitigation is most appropriate?', 'Emailing it to all staff', 'Adding it to the allow list', 'Disabling the firewall', 'Isolation in a sandbox', 'D', 'Isolation runs untrusted code in a contained environment so it can''t affect other systems. Allow listing it would let it run freely.'),
  (103, 'secplus-vulnerability-management', 'After a patch is applied, what is the best way to confirm the vulnerability is remediated?', 'Delete the scan report', 'Close the ticket without checking', 'Assume the patch worked', 'Rescan the system', 'D', 'Rescanning verifies the fix actually worked. Patches sometimes fail or need a reboot to take effect.'),
  (104, 'secplus-monitoring', 'Which tool provides summaries of network traffic flows, such as source, destination, ports, and byte counts, without capturing full packets?', 'NetFlow', 'A full packet capture', 'A vulnerability scanner', 'A SIEM dashboard only', 'A', 'NetFlow records metadata about conversations, which is useful for spotting unusual traffic and exfiltration. Full packet capture stores entire contents.'),
  (105, 'secplus-governance', 'What is the difference between centralized and decentralized security governance?', 'Centralized governance applies only to cloud', 'Centralized governance doesn''t use policies; decentralized governance does', 'Decentralized governance is required by law', 'Centralized decides from one authority; decentralized spreads decisions out', 'D', 'Centralized governance gives consistency, while decentralized governance allows local flexibility. Many organizations use a hybrid.'),
  (106, 'secplus-audits-assessments', 'Internal audits are primarily used to:', 'Attack the network from the internet', 'Evaluate whether controls work as intended', 'Negotiate vendor contracts', 'Replace the need for external regulatory examinations', 'B', 'Internal audits give management ongoing assurance and find issues before external auditors do. They complement, not replace, external audits.'),
  (107, 'secplus-malicious-activity', 'An attacker steals a password hash from memory and uses it directly to authenticate to other Windows systems without cracking it. What attack is this?', 'Pass the hash', 'A birthday attack', 'Password spraying', 'Typosquatting', 'A', 'Pass the hash uses the hash itself as the credential with protocols like NTLM. Limiting administrator credential use and enabling Credential Guard help prevent it.'),
  (108, 'secplus-secure-infrastructure', 'Which IPsec protocol provides both encryption and integrity for the packet payload?', 'Authentication Header (AH)', 'Encapsulating Security Payload (ESP)', 'Generic Routing Encapsulation', 'Internet Key Exchange alone', 'B', 'ESP encrypts and authenticates the payload. AH provides integrity and authentication but no encryption.'),
  (109, 'secplus-resilience-recovery', 'Which practice best protects backups from ransomware that encrypts everything it can reach on the network?', 'Keeping an offline or immutable copy of backups', 'Storing all backups on a mapped network drive', 'Running backups less often', 'Disabling backup encryption', 'A', 'Ransomware often targets reachable backups. Offline, air-gapped, or immutable copies can''t be encrypted by the attacker.'),
  (110, 'secplus-enterprise-security', 'Which port is used by HTTPS by default?', '80', '443', '22', '3389', 'B', 'HTTPS uses TCP 443. Port 80 is unencrypted HTTP, 22 is SSH, and 3389 is RDP.'),
  (111, 'secplus-change-management', 'Why should test results be reviewed before a change is approved for production?', 'To confirm the change works without causing new problems', 'To skip stakeholder notification for low-risk changes', 'To replace the need for a documented backout plan', 'To determine how long the maintenance window should be', 'A', 'Testing in a nonproduction environment validates the change and reveals side effects. Good test results don''t remove the need for a backout plan.'),
  (112, 'secplus-investigation-data', 'What is the value of automated reports in an investigation?', 'They give consistent summaries that reveal trends', 'They replace the need for human analysts to review the evidence', 'They contain full forensic disk images', 'They encrypt evidence for court', 'A', 'Automated reports highlight patterns, such as rising failed logins. Analysts still validate and interpret them.'),
  (113, 'secplus-identity-access', 'A firewall allows traffic based on administrator-defined conditions that apply to everyone, such as blocking all traffic to port 23. Which model is this?', 'Rule-based access control', 'Discretionary access control', 'Role-based access control', 'Mandatory access control', 'A', 'Rule-based access control applies the same rules to all subjects, regardless of identity. Firewall ACLs are a classic example.'),
  (114, 'secplus-security-concepts', 'In zero trust, what does adaptive identity mean?', 'Users keep the same access once they''ve authenticated on the internal network', 'Access decisions consider context such as location, device health, and behavior', 'Passwords are rotated automatically every 30 days', 'Accounts are shared across departments to reduce overhead', 'B', 'Adaptive identity evaluates risk signals at each request instead of trusting a single login. Trusting anyone on the internal network is exactly the perimeter model zero trust replaces.'),
  (115, 'secplus-data-protection', 'Why does the physical location of cloud data centers matter for data protection?', 'It only affects network speed', 'Data in the cloud has no single physical location, so no laws apply', 'Laws of the country where data resides may apply to it', 'Location never affects legal requirements', 'C', 'Data geolocation determines which laws and authorities apply. Organizations may need to choose cloud regions to meet regulations.'),
  (116, 'secplus-hardening', 'When hardening cloud infrastructure, which practice is most important?', 'Using the root account for daily tasks', 'Disabling detailed logging to reduce cloud storage and network costs', 'Making storage public for easier sharing', 'Least-privilege IAM and secure storage and network settings', 'D', 'Most cloud breaches come from misconfiguration and excessive permissions. Least privilege and secure defaults prevent many of them.'),
  (117, 'secplus-incident-response', 'Why is incident response training important for staff outside the security team?', 'So they can bypass security controls', 'So employees recognize and report incidents quickly', 'Training isn''t needed for non-security staff', 'So they can perform their own forensic analysis of affected systems', 'B', 'Users are often the first to notice phishing or odd behavior. Fast reporting shortens the time to detection.'),
  (118, 'secplus-cryptography', 'Which hashing algorithm should be avoided because practical collisions have been demonstrated?', 'SHA-512', 'SHA-256', 'SHA-3', 'MD5', 'D', 'Researchers can produce MD5 collisions, two inputs with the same hash, so it can''t be trusted for integrity or signatures. The SHA-2 and SHA-3 families remain secure.'),
  (119, 'secplus-threat-vectors', 'Which situation creates the greatest risk from unsupported systems?', 'A server runs an OS that no longer receives patches', 'A workstation is patched monthly through MDM', 'A laptop runs an OS version released last month', 'A server is covered by an active vendor support plan', 'A', 'Unsupported, end-of-life systems no longer receive patches, so new vulnerabilities stay open permanently. They should be upgraded, isolated, or retired.'),
  (120, 'secplus-vulnerabilities', 'A newly created virtual machine can read leftover data in memory or storage previously assigned to another tenant''s VM. What is this risk?', 'Race condition', 'Resource reuse', 'VM escape', 'Privilege escalation', 'B', 'Resource reuse occurs when memory or disk isn''t wiped before reallocation. Hypervisors should clear resources before assigning them to another VM.'),
  (121, 'secplus-architecture-models', 'An organization keeps most systems on-premises. Which responsibility does it have that a cloud customer might share with a provider?', 'Physical security, power, and hardware maintenance of the data center', 'None, because on-premises systems are managed by vendors', 'Only end-user training', 'Only application access control', 'A', 'On-premises means the organization handles everything, from the building and power to the applications. In the cloud, the provider takes on the physical layers.'),
  (122, 'secplus-risk-management', 'What is risk tolerance?', 'The total annual security budget approved by the board of directors', 'Acceptable deviation from risk appetite for a specific risk', 'The number of risks in the register', 'The time allowed to recover systems', 'B', 'Risk tolerance sets acceptable levels for specific risks, while appetite is the overall attitude toward risk. Exceeding tolerance triggers action.'),
  (123, 'secplus-malicious-activity', 'Malware hides deep in the operating system, conceals its own processes, and gives an attacker persistent privileged access. What is it?', 'A keylogger', 'A rootkit', 'Adware', 'Bloatware', 'B', 'Rootkits modify the OS or firmware to hide themselves and keep administrator-level access. They often require a full rebuild to remove.'),
  (124, 'secplus-secure-infrastructure', 'Administrators must connect to a hardened intermediate server before they can manage servers in a secure zone. What is this intermediate server?', 'A honeypot', 'A forward proxy', 'A load balancer', 'A jump server', 'D', 'A jump server, or bastion host, is the single controlled, monitored entry point for administration. It limits direct access paths into secure zones.'),
  (125, 'secplus-security-controls', 'An acceptable use policy tells employees what they must and must not do with company devices. Which control type is this?', 'Directive', 'Compensating', 'Detective', 'Corrective', 'A', 'Directive controls instruct people on expected behavior, as policies and procedures do. They don''t detect or fix anything on their own, which is why they''re usually paired with technical enforcement.'),
  (126, 'secplus-threat-actors', 'A competitor pays an employee to copy proprietary product designs onto a USB drive. Which motivation is most directly involved?', 'Espionage', 'War', 'Service disruption', 'Philosophical beliefs', 'A', 'Stealing trade secrets for competitive advantage is corporate espionage. The employee is also an insider threat, but the motive is gathering confidential information.'),
  (127, 'secplus-mitigations', 'A server is being retired. Which step is most important for decommissioning securely?', 'Sanitizing or destroying its storage', 'Removing its asset tag and serial number', 'Reusing its admin password on the replacement', 'Archiving its configuration files', 'A', 'Decommissioning must make sure data can''t be recovered from retired media. Forgotten, still-connected servers become unmanaged attack surfaces.'),
  (128, 'secplus-resilience-recovery', 'A team discusses how it would respond to a ransomware scenario, walking through roles and decisions around a conference table without touching any systems. What test is this?', 'Parallel processing', 'A tabletop exercise', 'A failover test', 'A full interruption test', 'B', 'Tabletop exercises are discussion-based and low-risk. They test plans and communication without affecting operations.'),
  (129, 'secplus-asset-management', 'Why must data retention requirements be considered when decommissioning a system?', 'Retention applies only to paper records', 'All data must be destroyed immediately', 'Decommissioned systems are exempt from retention', 'Some data must be kept for a required period', 'D', 'Regulations or legal holds may require keeping certain data for a set time. Destroying it too early can violate the law.'),
  (130, 'secplus-vulnerability-management', 'What is the advantage of a credentialed vulnerability scan over a non-credentialed one?', 'It exploits each flaw it finds to confirm the vulnerability is real', 'It doesn''t require authorization to run', 'It sees installed software and settings, finding more issues', 'It can''t be detected by network monitoring', 'C', 'Credentialed scans examine the system from the inside, which gives more accurate results. Non-credentialed scans see only what''s exposed externally.'),
  (131, 'secplus-monitoring', 'Which activity involves regularly checking systems for vulnerabilities and misconfigurations as part of monitoring?', 'Scanning', 'Tokenization', 'Archiving', 'Journaling', 'A', 'Regular vulnerability and configuration scanning keeps visibility current. It''s one of the core monitoring activities.'),
  (132, 'secplus-enterprise-security', 'An IDS detects attacks by comparing traffic to a database of known attack patterns. What detection method is this?', 'Signature-based', 'Heuristic only', 'Reputation-based', 'Anomaly-based', 'A', 'Signature-based detection is accurate for known attacks but misses new ones. Anomaly-based detection compares traffic against a baseline of normal behavior.'),
  (133, 'secplus-identity-access', 'Credentials that are created for a single session or task and then expire automatically are called:', 'Default credentials', 'Ephemeral credentials', 'Hard-coded credentials', 'Shared credentials', 'B', 'Ephemeral credentials exist only briefly, so stolen ones quickly become useless. They''re common in cloud and PAM tools.'),
  (134, 'secplus-automation', 'A pipeline automatically runs security tests on code every time a developer commits changes. What is this practice?', 'Waterfall release management', 'Manual peer code review', 'Scheduled tabletop testing', 'Continuous integration and testing', 'D', 'CI pipelines run automated tests, including security scans, on each change. Problems are caught early, when they''re cheapest to fix.'),
  (135, 'secplus-governance', 'Which document states, at a high level, management''s intent and direction for information security?', 'An information security policy', 'A best-practice guideline', 'A standard operating procedure', 'An incident response playbook', 'A', 'Policies are high-level, mandatory statements of intent approved by management. Procedures give step-by-step instructions to carry them out.'),
  (136, 'secplus-third-party-risk', 'Two government agencies document their intent to cooperate on a project, without a legally binding commitment. Which agreement fits?', 'Master service agreement (MSA)', 'Service level agreement (SLA)', 'Statement of work (SOW)', 'Memorandum of understanding (MOU)', 'D', 'An MOU expresses shared goals and is generally not legally binding. An MOA is more formal and spells out specific responsibilities.'),
  (137, 'secplus-compliance', 'Why does an organization need a data inventory for privacy compliance?', 'To know what personal data it holds and where', 'To avoid the need to encrypt data that isn''t on the list', 'To increase available storage capacity', 'To speed up database queries', 'A', 'You can''t protect or delete data you can''t find. A data inventory supports retention, access requests, and breach response.'),
  (138, 'secplus-audits-assessments', 'A red team attacks while a blue team defends, and both share findings to improve together. What is this collaborative approach called?', 'Integrated (purple team) testing', 'Unknown environment testing', 'Regulatory examination', 'Passive reconnaissance', 'A', 'Purple teaming combines offense and defense to improve detection and response. Red teams attack, and blue teams defend.'),
  (139, 'secplus-security-awareness', 'What is operational security (OPSEC) awareness for employees?', 'Running penetration tests', 'Not sharing details that could help attackers', 'Configuring firewalls on home routers used for remote work', 'Writing secure source code', 'B', 'Small details like travel plans, org charts, or badge photos can aid social engineering. OPSEC training teaches discretion.'),
  (140, 'secplus-malicious-activity', 'Which malware secretly records every keystroke to capture passwords?', 'A worm', 'A logic bomb', 'A keylogger', 'Adware', 'C', 'Keyloggers capture typed input, including credentials. MFA limits the damage, because a stolen password alone isn''t enough to log in.'),
  (141, 'secplus-secure-infrastructure', 'In an 802.1X deployment, what role does the RADIUS server play?', 'Supplicant', 'Authenticator', 'Access point client', 'Authentication server', 'D', 'The supplicant is the client device, the authenticator is the switch or access point, and the authentication server, usually RADIUS, verifies credentials.'),
  (142, 'secplus-cryptography', 'Which chip on a laptop''s motherboard stores keys for full-disk encryption and records boot measurements for secure boot?', 'Key management system (KMS)', 'Hardware security module (HSM)', 'Certificate revocation list (CRL)', 'Trusted Platform Module (TPM)', 'D', 'A TPM is built into the device to protect keys and support measured and secure boot. An HSM is a separate, often network-attached appliance for high-volume key operations.'),
  (143, 'secplus-threat-vectors', 'An attacker gains unauthorized access to a phone''s contacts and messages over Bluetooth. What is this called?', 'Jamming', 'Bluesnarfing', 'Bluejacking', 'Typosquatting', 'B', 'Bluesnarfing exploits Bluetooth to steal data. Keeping Bluetooth off or non-discoverable when not in use reduces the risk.'),
  (144, 'secplus-vulnerabilities', 'A user installs an app on their phone from a website instead of the official app store. What is this practice called?', 'Jailbreaking', 'Side loading', 'Rooting', 'Tethering', 'B', 'Side loading installs apps from outside the official store, skipping its security review. Jailbreaking or rooting removes OS restrictions, which is a separate step.'),
  (145, 'secplus-architecture-models', 'Which statement about high availability in architecture design is most accurate?', 'It removes the need for separate backups', 'It uses redundancy to minimize downtime', 'It requires all systems to run on-premises', 'It guarantees data is encrypted at rest', 'B', 'High availability uses redundant components and failover to minimize downtime. Backups are still needed, because redundancy faithfully replicates corruption and deletions.'),
  (146, 'secplus-risk-management', 'Risk identification is best described as:', 'Finding and documenting potential threats and vulnerabilities', 'Buying insurance to cover the cost of risks that are already known', 'Testing backups for recoverability', 'Deleting data that is no longer needed', 'A', 'You can''t manage risks you haven''t identified. Identification feeds the assessment and the register.'),
  (147, 'secplus-data-protection', 'A European company is required to keep citizens'' personal data within EU borders. What concept is this?', 'Data sovereignty', 'Tokenization', 'Data masking', 'Obfuscation', 'A', 'Data sovereignty means data is subject to the laws of the country where it is stored. That affects where cloud data can be located.'),
  (148, 'secplus-hardening', 'Which step should be taken when hardening a network switch?', 'Allow all VLANs on every access port', 'Disable unused ports and manage it over SSH', 'Keep the default SNMP community strings', 'Enable Telnet for remote management', 'B', 'Disabling unused ports and using encrypted management reduce attack paths. Telnet and default SNMP strings expose credentials.'),
  (149, 'secplus-incident-response', 'Why do forensic investigators create a hash of a disk image when they acquire it?', 'To compress the image for faster transfer', 'To encrypt the image for secure storage', 'To prove later that the evidence is unchanged', 'To identify known malware files on the disk', 'C', 'Matching hashes before and after analysis show the evidence is unchanged. Investigators work on copies, not the original.'),
  (150, 'secplus-security-concepts', 'A file named passwords.xlsx containing fake credentials is placed on a file server, and any access to it triggers an alert. What is this?', 'A sandbox', 'A honeyfile', 'A honeypot', 'A honeynet', 'B', 'A honeyfile is a decoy file that attracts attackers and reveals their activity. A honeypot is a whole decoy system, and a honeynet is a network of them.'),
  (151, 'secplus-identity-access', 'A user signs in once and can then reach email, HR, and expense apps without signing in again. What is this?', 'Federation only', 'Password vaulting', 'Single sign-on (SSO)', 'Multifactor authentication', 'C', 'SSO lets one authentication grant access to many applications. It improves usability but makes that one login a high-value target, so MFA is important.'),
  (152, 'secplus-change-management', 'Why are changes typically scheduled during a maintenance window?', 'To avoid the need for change approval', 'Because auditors require all changes to happen at night', 'To minimize disruption to users and business operations', 'To skip writing a backout plan', 'C', 'Maintenance windows are low-impact times agreed with the business, so any downtime affects as few people as possible. They don''t replace approval or rollback planning.'),
  (153, 'secplus-investigation-data', 'Which data source contains the full contents of network communications for detailed analysis?', 'SNMP traps', 'Dashboards', 'NetFlow records', 'Packet captures', 'D', 'Packet captures (PCAPs) store complete packets, including payloads. NetFlow stores only summary metadata about connections.'),
  (154, 'secplus-resilience-recovery', 'During a power outage, what is the main role of a generator?', 'To back up data offsite', 'To provide long-term power once it starts up', 'To filter network traffic', 'To provide instant power with no delay the moment an outage begins', 'B', 'Generators run for long periods on fuel but need time to start. A UPS covers that startup gap.'),
  (155, 'secplus-enterprise-security', 'Which mechanism tells receiving mail servers what to do with messages that fail SPF or DKIM checks, and sends reports back to the domain owner?', 'DKIM', 'SMTP', 'SPF', 'DMARC', 'D', 'DMARC policies, none, quarantine, or reject, tell receivers how to handle failures and provide reporting. It ties SPF and DKIM to the visible From domain.'),
  (156, 'secplus-malicious-activity', 'An authentication log shows thousands of accounts each receiving one or two login attempts with the password Spring2026!. What attack is this?', 'Password spraying', 'Brute force against a single account', 'Pass the hash', 'Credential replay', 'A', 'Password spraying tries a few common passwords across many accounts to avoid lockouts. A brute-force attack hammers one account with many passwords.'),
  (157, 'secplus-secure-infrastructure', 'Which device distributes incoming requests across several web servers to improve availability and performance?', 'A network tap', 'A jump server', 'An IDS', 'A load balancer', 'D', 'Load balancers spread traffic and route around failed servers. Many can also terminate TLS and help absorb some attacks.'),
  (158, 'secplus-threat-actors', 'Which threat actor attribute describes whether an attacker has the money to buy zero-day exploits and custom tools?', 'Motivation', 'Attack vector', 'Internal versus external', 'Resources and funding', 'D', 'Resources and funding determine the tools and time an actor can invest. Internal versus external describes where the actor sits relative to the organization.'),
  (159, 'secplus-mitigations', 'A vendor releases a patch for a critical, actively exploited vulnerability. What is the best course of action?', 'Test and deploy the patch as quickly as possible', 'Disable all logging until the patch is applied', 'Wait for the next annual maintenance cycle', 'Uninstall the antivirus to avoid conflicts', 'A', 'Actively exploited critical flaws should be patched urgently, using an expedited change process. Waiting months leaves the systems exposed.'),
  (160, 'secplus-vulnerability-management', 'A development team uses a tool that alerts when a third-party library in their application has a known vulnerability. What is this?', 'A penetration test of the production system', 'Package monitoring (software composition analysis)', 'Static analysis of the team''s own source code', 'Dynamic analysis of the running application', 'B', 'Package monitoring tracks dependencies for known vulnerabilities. Modern applications rely heavily on third-party code, which makes this critical.'),
  (161, 'secplus-monitoring', 'Which protocol lets network devices send unsolicited alerts, called traps, to a management station?', 'LDAP', 'SMTP', 'SNMP', 'NTP', 'C', 'SNMP traps notify managers of events such as interface failures. SNMPv3 should be used because it adds authentication and encryption.'),
  (162, 'secplus-governance', 'Who is responsible for determining a dataset''s classification and who may access it?', 'The data custodian', 'The data processor', 'The end user', 'The data owner', 'D', 'The data owner, usually a senior business leader, is accountable for the data and its classification. The custodian implements the technical protections.'),
  (163, 'secplus-audits-assessments', 'A tester searches public websites, social media, and DNS records without directly touching the target''s systems. What is this?', 'Privilege escalation', 'Exploitation', 'Active reconnaissance', 'Passive reconnaissance', 'D', 'Passive reconnaissance gathers information without interacting with target systems, so it''s hard to detect. Active reconnaissance, such as port scanning, touches the target.'),
  (164, 'secplus-cryptography', 'Which type of encryption protects everything on a laptop''s drive, including the operating system and temporary files, if the laptop is stolen?', 'Transport encryption', 'Record-level encryption', 'File-level encryption', 'Full-disk encryption', 'D', 'Full-disk encryption covers the entire drive, so nothing is readable without the key. File-level encryption protects only selected files and can miss temporary copies.'),
  (165, 'secplus-threat-vectors', 'An attacker in a crowded airport watches over a traveler''s shoulder as they type their password. What technique is this?', 'Tailgating', 'Dumpster diving', 'Pretexting', 'Shoulder surfing', 'D', 'Shoulder surfing is observing someone''s screen or keyboard to capture information. Privacy screens help prevent it.'),
  (166, 'secplus-vulnerabilities', 'A vulnerability is exploited before the vendor knows about it or has released a patch. What is it called?', 'End-of-life', 'A misconfiguration', 'A legacy vulnerability', 'A zero-day', 'D', 'Zero-day vulnerabilities have no patch available, so defense relies on layered controls and behavior-based detection. End-of-life systems have known flaws that will never be patched.'),
  (167, 'secplus-architecture-models', 'What is a key security benefit of virtualization?', 'Workloads are isolated, and snapshots allow quick rollback', 'VMs don''t need patching once deployed', 'The hypervisor replaces the need for network firewalls between workloads', 'VMs can''t be reached over the network', 'A', 'Virtualization isolates workloads, and snapshots make rollback easy. VMs still need patching and network protections like physical machines.'),
  (168, 'secplus-risk-management', 'Who should be assigned as the risk owner for a risk in the register?', 'The vendor whose product is affected', 'Whoever first reported the risk to the security team', 'The external auditor', 'The person accountable for managing that risk', 'D', 'Risk owners have the authority and accountability to manage specific risks. Clear ownership keeps risks from being ignored.'),
  (169, 'secplus-security-controls', 'Which of the following is a technical control?', 'Background checks before hiring', 'A documented incident response plan', 'A locked server room door', 'Requiring MFA for VPN connections', 'D', 'Technical controls are enforced by hardware or software, such as MFA. Background checks are operational, a locked door is physical, and a documented plan is managerial.'),
  (170, 'secplus-third-party-risk', 'Which contract clause allows a customer to inspect a vendor''s security controls?', 'A right-to-audit clause', 'A termination clause', 'A non-compete clause', 'A force majeure clause', 'A', 'A right-to-audit clause lets the customer verify the vendor''s security. Without it, the customer depends only on the vendor''s claims.'),
  (171, 'secplus-compliance', 'A company loses a government contract because it failed a required security assessment. What consequence of noncompliance is this?', 'Contractual impact', 'Loss of license', 'Improved reputation', 'Sanctions on individuals only', 'A', 'Contracts often require compliance, and failing can end the agreement or block future bids. Fines and reputational damage are other consequences.'),
  (172, 'secplus-data-protection', 'A barcode or machine-readable QR code that encodes customer information is an example of which data type?', 'Public data', 'Non-human-readable data', 'Trade secret', 'Human-readable data', 'B', 'Non-human-readable data requires a machine to interpret. It may still contain sensitive information and need protection.'),
  (173, 'secplus-hardening', 'Which cookie attribute ensures a cookie is sent only over HTTPS connections?', 'Expires', 'SameSite=None', 'HttpOnly', 'Secure', 'D', 'The Secure flag keeps cookies off unencrypted connections. HttpOnly keeps JavaScript from reading the cookie, which helps against XSS.'),
  (174, 'secplus-incident-response', 'Which activity is part of the analysis phase of incident response?', 'Rebuilding the affected servers from clean, verified backups', 'Holding a lessons learned meeting', 'Training staff on response procedures', 'Determining the incident''s scope and impact', 'D', 'Analysis confirms the incident and works out what''s affected and how. That shapes how containment should be done.'),
  (175, 'secplus-identity-access', 'A military system grants access by comparing a user''s clearance level to a document''s classification label. Which model is this?', 'Mandatory access control (MAC)', 'Role-based access control', 'Attribute-based access control', 'Discretionary access control', 'A', 'MAC enforces labels set by administrators or policy, and users can''t override them. It''s common in government and military systems.'),
  (176, 'secplus-malicious-activity', 'A web page tricks a logged-in user''s browser into submitting a funds transfer request to their bank without their knowledge. What attack is this?', 'Stored XSS', 'Directory traversal', 'Cross-site request forgery (CSRF)', 'Server-side request forgery (SSRF)', 'C', 'CSRF abuses the user''s active session to send unwanted requests. Anti-CSRF tokens and SameSite cookies prevent it.'),
  (177, 'secplus-secure-infrastructure', 'What is the main tradeoff of placing an IPS inline?', 'It can only alert on attacks it sees, and it can never block them', 'It can block attacks, but failures can disrupt traffic', 'It replaces the need for a firewall', 'It can''t see traffic inside the network', 'B', 'Inline placement allows prevention but adds a point of failure and the risk of false positives blocking real users. Its failure mode must be chosen carefully.'),
  (178, 'secplus-resilience-recovery', 'What does replication provide that periodic backups do not?', 'A near-real-time copy of data on another system', 'Automatic malware removal', 'Protection against accidental deletion that is copied over', 'A guaranteed point-in-time history', 'A', 'Replication keeps a secondary copy current, which minimizes data loss. But it also copies deletions and corruption, so backups are still needed.'),
  (179, 'secplus-enterprise-security', 'A web filter uses a URL''s reputation score and its content category to decide whether to block it. What benefit does this provide?', 'It blocks risky sites, including newly flagged ones', 'It encrypts all outbound web traffic', 'It blocks phishing emails before delivery', 'It speeds up downloads by caching popular sites for all users', 'A', 'Reputation and categorization block risky sites without manually listing every URL. Email filtering is handled by a separate gateway.'),
  (180, 'secplus-security-concepts', 'Comparing a downloaded file''s hash to the hash published by the vendor primarily verifies which part of the CIA triad?', 'Availability', 'Confidentiality', 'Integrity', 'Authentication', 'C', 'Matching hashes show the file hasn''t been altered, which is integrity. Hashing doesn''t hide data, so it provides no confidentiality.'),
  (181, 'secplus-asset-management', 'Why is an accurate asset inventory the foundation of security operations?', 'It removes the need for network firewalls around known devices', 'It encrypts asset data automatically', 'It''s required mainly for tax purposes', 'You can''t protect assets you don''t know you have', 'D', 'Unknown assets go unpatched and unmonitored, which makes them easy targets. Inventory supports vulnerability management, incident response, and compliance.'),
  (182, 'secplus-automation', 'When an employee''s account is flagged as compromised, an automated workflow disables it immediately. What use case is this?', 'Continuous integration and testing', 'Automated ticket escalation', 'Automatically disabling access on an event', 'Automated user provisioning', 'C', 'Automatically disabling access contains threats within seconds. Waiting for manual action gives attackers more time.'),
  (183, 'secplus-security-awareness', 'Why should employees be trained never to plug in unknown USB drives or charging cables?', 'They void the laptop''s hardware warranty', 'They always damage the USB port', 'They can carry malware or malicious hardware', 'They transfer data too slowly to be useful', 'C', 'Malicious USB devices and cables can inject keystrokes or install malware. Unknown devices should be turned in to IT.'),
  (184, 'secplus-cryptography', 'What does a server administrator submit to a certificate authority to request a new certificate?', 'A certificate signing request (CSR)', 'A certificate revocation list', 'The server''s private key', 'An OCSP stapled response', 'A', 'A CSR contains the public key and identifying information for the CA to sign. The private key never leaves the server; sending it would compromise the certificate.'),
  (185, 'secplus-threat-vectors', 'Which attack involves sending unsolicited messages to nearby Bluetooth devices?', 'Bluejacking', 'Bluesnarfing', 'Evil twin', 'War driving', 'A', 'Bluejacking sends unwanted messages over Bluetooth and is mostly a nuisance. Bluesnarfing is more serious: it steals data from the device.'),
  (186, 'secplus-vulnerabilities', 'A login form passes the input '' OR 1=1 -- directly to the database and lets the attacker in. What vulnerability is present?', 'Cross-site scripting', 'Buffer overflow', 'SQL injection', 'Cross-site request forgery', 'C', 'Unsanitized input changes the logic of the SQL query. Parameterized queries, or prepared statements, prevent this.'),
  (187, 'secplus-architecture-models', 'A company moves workloads to the cloud partly so the provider handles the risk of hardware failure. Which consideration is this?', 'Inability to patch', 'Responsiveness', 'Risk acceptance', 'Risk transference', 'D', 'Shifting some responsibility to a provider through contracts and SLAs transfers risk. The customer is still accountable for its own data and configuration.'),
  (188, 'secplus-risk-management', 'A server worth $200,000 would lose 25 percent of its value in a flood, and a flood is expected once every two years. What is the annualized loss expectancy (ALE)?', '$100,000', '$25,000', '$12,500', '$50,000', 'B', 'SLE = $200,000 x 0.25 = $50,000. The ARO is 0.5 (once every two years), so ALE = $50,000 x 0.5 = $25,000.'),
  (189, 'secplus-threat-actors', 'Which attribute most distinguishes an insider threat from an external threat actor?', 'Authorized access and knowledge of internal systems', 'Greater funding and access to custom-built attack tools and exploits', 'Reliance on zero-day exploits to gain entry', 'A consistent motivation of financial gain', 'A', 'Insiders already have access and know where valuable data lives, so they can bypass many perimeter controls. Their motives vary and aren''t always financial.'),
  (190, 'secplus-mitigations', 'Which principle is applied when a user is given only the permissions needed for their job?', 'Separation of duties', 'Least privilege', 'Implicit trust', 'Defense in depth', 'B', 'Least privilege limits the damage a compromised or careless account can do. Separation of duties splits critical tasks between people.'),
  (191, 'secplus-vulnerability-management', 'What does the Common Vulnerability Scoring System (CVSS) provide?', 'A list of known exploited vulnerabilities', 'A patch release schedule for each vendor', 'A score that rates a vulnerability''s severity', 'A unique identifier for each vulnerability', 'C', 'CVSS rates severity from 0 to 10 based on factors like exploitability and impact. CVE provides the unique identifier.'),
  (192, 'secplus-monitoring', 'A DLP system detects an employee uploading a file of Social Security numbers to personal cloud storage. What does DLP stand for and do?', 'Data loss prevention; it detects and blocks sensitive data leaving', 'Dynamic link protocol; it routes traffic between sites', 'Domain lookup protection; it filters DNS queries', 'Disk level partitioning; it encrypts drive partitions', 'A', 'DLP inspects data in motion, at rest, and in use against policies. It can block, alert, or encrypt sensitive data.'),
  (193, 'secplus-governance', 'Which standard would specify minimum password length and lockout thresholds?', 'A disaster recovery plan', 'A password standard', 'A memorandum of agreement', 'A business continuity policy', 'B', 'A password standard turns the access policy into specific, measurable rules. It supports consistent enforcement.'),
  (194, 'secplus-audits-assessments', 'Why do customers often prefer independent third-party audits of their vendors?', 'They replace the need for contracts', 'They are always free to the vendor', 'They provide unbiased assurance about controls', 'They guarantee that the vendor won''t suffer a breach', 'C', 'Independence reduces conflicts of interest in findings. Examples include SOC 2 and ISO 27001 certification audits.'),
  (195, 'secplus-identity-access', 'Before issuing credentials to a new remote employee, the company verifies their government ID and identity documents. What is this?', 'Identity proofing', 'Federation', 'Attestation', 'Provisioning', 'A', 'Identity proofing confirms a person is who they claim to be before an account is created. Provisioning is creating the account afterward.'),
  (196, 'secplus-change-management', 'A legacy application can''t be patched without breaking a critical vendor integration. What is the most appropriate action?', 'Document the risk and apply compensating controls until it''s replaced', 'Remove the application from the asset inventory and CMDB', 'Accept the risk informally without recording the decision', 'Apply the patch in production now and repair the vendor integration afterward', 'A', 'Legacy applications often can''t follow normal patching, so the risk must be documented and reduced with other controls. Patching untested could break the integration.'),
  (197, 'secplus-malicious-activity', 'A new laptop ships with many trial apps and utilities that the user didn''t request and that slow the system down. What is this?', 'A rootkit', 'A worm', 'Ransomware', 'Bloatware', 'D', 'Bloatware is unnecessary preinstalled software. It''s usually not malicious, but it increases the attack surface and should be removed.'),
  (198, 'secplus-secure-infrastructure', 'Which device is placed inline and can actively block malicious traffic?', 'An intrusion prevention system', 'A passive sensor', 'A network tap', 'An intrusion detection system on a SPAN port', 'A', 'Inline devices sit in the traffic path, so they can drop packets. An IDS connected to a tap or SPAN port only sees copies of traffic and can alert but not block.'),
  (199, 'secplus-data-protection', 'A company''s secret recipe gives it a competitive advantage and isn''t protected by a patent. What type of data is this?', 'A trade secret', 'Regulated data', 'Public data', 'Legal data', 'A', 'Trade secrets are valuable because they stay confidential. Unlike patents, their protection depends on keeping them secret.'),
  (200, 'secplus-hardening', 'What is the main goal of hardening a server?', 'Improve its performance under heavy load', 'Reduce its attack surface with secure settings', 'Make it reachable from more networks', 'Increase its capacity to handle more users', 'B', 'Hardening disables what isn''t needed, applies patches, and configures security settings. Every unnecessary feature is a potential vulnerability.'),
  (201, 'secplus-incident-response', 'Which tool prevents changes to a drive while investigators acquire its data?', 'A load balancer', 'A network tap', 'A write blocker', 'A degausser', 'C', 'Write blockers allow reading but block writes, which preserves evidence. A degausser erases magnetic media.'),
  (202, 'secplus-investigation-data', 'Which data source shows alerts generated when network traffic matched a known attack signature?', 'IDS/IPS logs', 'DHCP logs', 'Backup logs', 'Printer logs', 'A', 'IDS and IPS logs record detected and blocked attacks. They help identify what attack was attempted and against which hosts.'),
  (203, 'secplus-resilience-recovery', 'Which test actually switches production workloads to a secondary system to confirm it works?', 'A walkthrough', 'A failover test', 'A tabletop exercise', 'A document review', 'B', 'Failover testing proves redundant systems really take over. It carries some risk, so it''s usually scheduled carefully.'),
  (204, 'secplus-enterprise-security', 'Before a laptop joins the network, the system checks that its antivirus is current and it''s fully patched. What technology is this?', 'File integrity monitoring', 'DNS filtering', 'Network access control (NAC)', 'Data masking', 'C', 'NAC checks device health and identity before granting access. Noncompliant devices can be quarantined or sent for remediation.'),
  (205, 'secplus-security-controls', 'A legacy application cannot support multifactor authentication, so the company places it on an isolated network segment with strict access rules. What type of control is the segmentation?', 'Directive', 'Deterrent', 'Corrective', 'Compensating', 'D', 'A compensating control is an alternative safeguard used when the primary control (here, MFA) can''t be implemented. Segmentation reduces the risk the missing MFA would have addressed.'),
  (206, 'secplus-third-party-risk', 'Which agreement defines measurable performance commitments, such as 99.9 percent uptime, between a provider and a customer?', 'Memorandum of understanding (MOU)', 'Non-disclosure agreement (NDA)', 'Service level agreement (SLA)', 'Business partners agreement (BPA)', 'C', 'SLAs specify performance metrics and penalties for missing them. They set clear service expectations.'),
  (207, 'secplus-compliance', 'Why might organizations automate compliance monitoring?', 'To detect violations faster and more consistently', 'To keep noncompliance hidden from regulators', 'To remove the need for written policies', 'To avoid the need for external audits', 'A', 'Automated tools can track configuration compliance in real time. That reduces manual effort and audit surprises.'),
  (208, 'secplus-cryptography', 'A retailer replaces card numbers with random values that map back to the real numbers only in a secure vault. What is this?', 'Hashing', 'Tokenization', 'Steganography', 'Data masking', 'B', 'Tokenization substitutes sensitive data with a token that has no mathematical relationship to the original; only the vault can map it back. Hashing is one-way and can''t be reversed to recover the card number.'),
  (209, 'secplus-threat-vectors', 'An attacker plugs a malicious device into an unused, active network jack in a conference room. Which threat vector does this exploit?', 'A watering hole website', 'A typosquatted domain', 'A malicious voice call', 'An unsecure wired network', 'D', 'Live, unused network ports let anyone connect to the internal network. Port security, 802.1X, or disabling unused ports addresses this.'),
  (210, 'secplus-vulnerabilities', 'A program checks that a user may access a file, but an attacker swaps the file before it is opened. What is this vulnerability?', 'Memory leak in the access check', 'Time-of-check to time-of-use (TOCTOU) race condition', 'Directory traversal through the file path', 'Buffer overflow in the file handler', 'B', 'A TOCTOU race exploits the gap between checking a condition and acting on it. The fix is making the check and the use a single atomic operation.'),
  (211, 'secplus-architecture-models', 'In a SaaS offering such as a hosted email service, which responsibility almost always remains with the customer?', 'Managing user access and protecting their own data', 'Patching the application servers', 'Maintaining the data center''s physical security', 'Updating the hypervisor', 'A', 'Even in SaaS, customers control who has access and what data they put in the service. The provider runs the application and infrastructure.'),
  (212, 'secplus-risk-management', 'In risk analysis, what does impact refer to?', 'The probability that the risk will actually occur in a given year', 'The magnitude of harm if a risk is realized', 'The number of controls in place', 'The time between failures', 'B', 'Risk is generally the likelihood of an event combined with its impact. Impact can be financial, operational, reputational, or legal.'),
  (213, 'secplus-identity-access', 'A login is allowed only if the user''s IP address is within the company''s country. Which authentication factor is this?', 'Something you know', 'Something you are', 'Something you have', 'Somewhere you are', 'D', 'Location-based factors use geolocation or network location. They''re usually combined with other factors.'),
  (214, 'secplus-security-concepts', 'A fake API key is planted in a code repository, and any attempt to use it raises an alert. This is an example of a:', 'Honeytoken', 'Honeynet', 'Honeypot', 'Digital certificate', 'A', 'A honeytoken is fake data, such as credentials or records, that has no legitimate use, so any use signals an intrusion. A honeypot is a decoy system, not a piece of data.'),
  (215, 'secplus-malicious-activity', 'Malware spreads by itself from computer to computer across the network without any user action. What is it?', 'A virus', 'A logic bomb', 'A trojan', 'A worm', 'D', 'Worms self-propagate by exploiting network vulnerabilities. A virus needs a user to run an infected file or program to spread.'),
  (216, 'secplus-secure-infrastructure', 'In IPsec tunnel mode, what is encrypted?', 'Only the payload, with the original header left intact', 'Nothing; tunnel mode only authenticates', 'The entire original IP packet, including its header', 'Only the TCP header', 'C', 'Tunnel mode wraps the whole original packet in a new one, hiding internal addresses, which suits site-to-site VPNs. Transport mode encrypts only the payload.'),
  (217, 'secplus-threat-actors', 'A recently fired database administrator uses credentials that were never revoked to delete production records. What best describes this attacker and motive?', 'An unskilled attacker motivated by curiosity', 'An insider threat motivated by revenge', 'A hacktivist motivated by ideology', 'A nation-state motivated by espionage', 'B', 'The attacker had legitimate insider access and acted out of a grievance. Prompt deprovisioning during offboarding would have prevented this attack.'),
  (218, 'secplus-mitigations', 'Which mitigation would best stop a worm from spreading from the user network to the database servers?', 'Requiring longer passwords for all users', 'Full-disk encryption on every database server in the data center', 'A data loss prevention policy on email', 'Segmentation with firewall rules between the networks', 'D', 'Segmentation blocks lateral movement between network zones. Strong passwords don''t stop a worm exploiting a network vulnerability.'),
  (219, 'secplus-vulnerability-management', 'Why might a vulnerability be granted an exemption from remediation?', 'The system owner prefers not to patch', 'The business formally accepts the risk', 'The scan cost more than the fix', 'The vulnerability has a high CVSS score', 'B', 'Exemptions are formal, documented risk acceptances, usually time-limited and approved by risk owners. They shouldn''t be used to avoid inconvenient work.'),
  (220, 'secplus-monitoring', 'A team compares server configurations against CIS Benchmarks. What are these benchmarks?', 'Signature lists of known malware', 'Federal regulations for data centers', 'Consensus-based secure configuration guidelines', 'Performance tests for server CPUs', 'C', 'CIS Benchmarks give detailed hardening recommendations for many platforms. They''re commonly used as secure baselines.'),
  (221, 'secplus-governance', 'Why must security policies be reviewed and revised periodically?', 'Reviews replace the need for training', 'Threats, technology, laws, and business needs change', 'Policies legally expire after one year unless they are re-signed', 'Revisions are only needed after a breach', 'B', 'Regular reviews keep policies relevant and effective. Outdated policies may not address current risks or regulations.'),
  (222, 'secplus-audits-assessments', 'A government agency inspects a bank''s security controls to verify regulatory compliance. What type of assessment is this?', 'Tabletop exercise', 'Bug bounty', 'Internal self-assessment', 'Regulatory examination (external)', 'D', 'Regulators conduct external examinations to enforce compliance. Findings can lead to penalties or required corrective actions.'),
  (223, 'secplus-data-protection', 'Which data protection method makes source code harder to understand without changing what it does?', 'Hashing', 'Obfuscation', 'Geofencing', 'Segmentation', 'B', 'Obfuscation makes code or data difficult to interpret, slowing reverse engineering. It doesn''t provide the strong protection of encryption.'),
  (224, 'secplus-hardening', 'Why should Bluetooth be disabled or set to non-discoverable on mobile devices when it isn''t needed?', 'To stop apps from using cellular data', 'To reduce exposure to attacks like bluesnarfing', 'To prevent the battery from overheating', 'Because Bluetooth disables Wi-Fi encryption', 'B', 'Bluetooth is an attack vector, and turning it off when unused shrinks the attack surface. It also saves power, but security is the main reason.'),
  (225, 'secplus-incident-response', 'What is e-discovery?', 'Searching the dark web for data leaked about the organization', 'Collecting and producing electronic information for legal cases', 'Scanning the network for new devices', 'Discovering new strains of malware', 'B', 'E-discovery handles electronic evidence for litigation. Legal holds and good records management support it.'),
  (226, 'secplus-resilience-recovery', 'What is the purpose of a continuity of operations plan (COOP)?', 'To schedule routine patching windows', 'To keep essential functions running during a disruption', 'To define how software licenses are tracked across the company', 'To set password and lockout requirements', 'B', 'A COOP ensures critical business functions continue during emergencies. It covers people, facilities, and processes, not just IT.'),
  (227, 'secplus-enterprise-security', 'Which secure protocol is used to query a directory service over an encrypted connection?', 'LDAPS on port 636', 'LDAP on port 389', 'SMTP on port 25', 'SNMP on port 161', 'A', 'LDAPS wraps LDAP in TLS, protecting credentials and directory data. Plain LDAP on 389 is unencrypted unless StartTLS is used.'),
  (228, 'secplus-cryptography', 'Which key is used to create a digital signature?', 'The sender''s public key', 'A shared symmetric key', 'The sender''s private key', 'The recipient''s public key', 'C', 'The sender signs with their private key, and anyone can verify with the matching public key. Signing with a shared symmetric key couldn''t prove which party sent the message.'),
  (229, 'secplus-threat-vectors', 'An attacker poses as a contractor sent to inspect the fire suppression system and uses a convincing backstory to get into the server room. What technique is this?', 'Pretexting', 'Shoulder surfing', 'Typosquatting', 'Smishing', 'A', 'Pretexting creates a believable scenario to gain trust and access. Shoulder surfing is watching someone enter information.'),
  (230, 'secplus-vulnerabilities', 'Why are legacy systems often a security concern even when still supported?', 'They store data in formats that can''t be encrypted', 'They can''t be segmented from the rest of the network', 'They are always the first systems targeted by newly released zero-day exploits', 'They may depend on outdated protocols and can''t run modern controls', 'D', 'Legacy systems often depend on old protocols, weak authentication, or software that can''t run modern endpoint agents. Isolation and compensating controls help reduce the risk.'),
  (231, 'secplus-architecture-models', 'A nuclear plant''s control network has no physical or wireless connection to any other network. What is this design called?', 'Logical segmentation', 'Hybrid cloud', 'Air gapping', 'Software-defined networking', 'C', 'An air gap physically isolates a network. It''s very strong, but it can still be bridged by removable media, as Stuxnet showed.'),
  (232, 'secplus-risk-management', 'What is the difference between qualitative and quantitative risk analysis?', 'Qualitative uses only dollar values; quantitative uses expert opinion', 'Quantitative never uses numbers', 'Qualitative uses ratings; quantitative uses numeric values', 'Quantitative is based only on opinions', 'C', 'Qualitative analysis is faster and subjective. Quantitative analysis assigns monetary values such as SLE and ALE.'),
  (233, 'secplus-identity-access', 'Why is interoperability important when choosing identity solutions?', 'It applies only to hardware tokens', 'It allows shorter passwords to be used across connected systems', 'Systems must work together through standards like SAML', 'It removes the need for authentication', 'C', 'Standards-based identity lets SSO and federation work across vendors and cloud services. Proprietary solutions can create silos.'),
  (234, 'secplus-malicious-activity', 'An attacker in a parking lot sets up an access point with the same SSID as the company''s network to capture employee logins. What is this?', 'A rogue access point installed by an employee', 'Bluejacking', 'An evil twin', 'War driving', 'C', 'An evil twin impersonates a legitimate wireless network to intercept traffic or credentials. 802.1X with certificate validation helps clients reject fake networks.'),
  (235, 'secplus-secure-infrastructure', 'Employees'' web traffic passes through a server that filters content, caches pages, and logs requests. What is this?', 'A jump server', 'A reverse proxy', 'A VPN concentrator', 'A forward proxy', 'D', 'A forward proxy acts on behalf of internal clients going out to the internet. A reverse proxy sits in front of internal servers to handle incoming requests.'),
  (236, 'secplus-asset-management', 'A vendor shreds a company''s old hard drives and provides a document listing the serial numbers destroyed. What is this document called?', 'A service level agreement', 'A memorandum of understanding', 'A certificate signing request', 'A certificate of destruction', 'D', 'A certificate of destruction proves media was properly destroyed, which supports compliance and audits. Keep it as part of disposal records.'),
  (237, 'secplus-automation', 'What is a key security benefit of automating user account provisioning?', 'Consistent accounts with correct permissions', 'No need for an offboarding process', 'Administrator rights for every new user', 'No need for user authentication', 'A', 'Automation applies standard role-based access every time. Automated deprovisioning also removes access quickly when people leave.'),
  (238, 'secplus-security-awareness', 'What is the primary goal of running simulated phishing campaigns for employees?', 'To identify and discipline employees who click on links', 'To test the email server''s capacity', 'To train employees to recognize and report phishing', 'To collect employees'' passwords', 'C', 'Simulations build recognition skills and measure progress. Focusing on education rather than punishment encourages reporting.'),
  (239, 'secplus-change-management', 'Why do change requests often note whether a service or application restart is required?', 'Restarts are required to update the asset inventory system', 'Restarts cause downtime that must be scheduled and communicated', 'Restarts reset security controls to their default settings', 'Restarts automatically roll back any changes that were made', 'B', 'A restart interrupts service, so it affects scheduling, stakeholder notification, and the maintenance window. Restarting doesn''t undo a change.'),
  (240, 'secplus-investigation-data', 'Why are dashboards useful during an active incident?', 'They summarize key indicators in real time', 'They replace the incident response plan', 'They store full packet captures', 'They eradicate malware automatically', 'A', 'Dashboards help responders see the scope and trends at a glance. Analysts drill into raw logs for details.'),
  (241, 'secplus-security-controls', 'A company posts signs at its entrances warning that the premises are under video surveillance. Which control type does the sign itself represent?', 'Corrective', 'Detective', 'Compensating', 'Deterrent', 'D', 'A warning sign discourages would-be intruders before they act, which makes it deterrent. The cameras behind it would be detective, but the sign records nothing on its own.'),
  (242, 'secplus-third-party-risk', 'A company signs one agreement with a consultancy defining general terms, then issues separate documents for each specific project. What is the overarching agreement called?', 'Work order (statement of work)', 'Non-disclosure agreement', 'Master service agreement (MSA)', 'Memorandum of agreement', 'C', 'An MSA sets the general terms for the relationship. Work orders or statements of work define each project''s specific deliverables.'),
  (243, 'secplus-compliance', 'An organization regularly submits compliance reports to a regulator. What type of reporting is this?', 'External compliance reporting', 'Incident triage', 'Internal compliance reporting', 'Vulnerability reporting', 'A', 'External reporting goes to regulators, customers, or auditors. Internal reporting informs management and the board.'),
  (244, 'secplus-security-concepts', 'Which sensor type detects the heat signature of a person entering a room?', 'Infrared', 'Pressure', 'Ultrasonic', 'Microwave', 'A', 'Infrared sensors detect heat emitted by bodies. Pressure sensors detect weight on a surface, and ultrasonic and microwave sensors detect motion through reflected waves.'),
  (245, 'secplus-threat-actors', 'An employee accidentally emails a spreadsheet of customer data to the wrong external address. How is this best classified?', 'An organized crime operation', 'An unintentional insider threat', 'A hacktivist data leak', 'A nation-state espionage attack', 'B', 'Insider threats include careless or accidental actions, not just malicious ones. Training and DLP controls help reduce this kind of mistake.'),
  (246, 'secplus-mitigations', 'A company removes unused software from its servers. What does this primarily accomplish?', 'It disables logging', 'It increases the number of open ports', 'It removes the need for patching', 'It reduces the attack surface', 'D', 'Every installed program is a potential vulnerability. Removing what isn''t needed means fewer things to patch and exploit.'),
  (247, 'secplus-vulnerability-management', 'A company invites outside security researchers to find and report vulnerabilities in exchange for rewards. What is this?', 'A bug bounty program', 'A penetration test by employees', 'A tabletop exercise', 'A vulnerability scan', 'A', 'Bug bounties pay researchers for responsibly disclosed vulnerabilities. They''re a form of responsible disclosure program.'),
  (248, 'secplus-monitoring', 'Why are logs archived for long periods?', 'Because regulations say logs can never be deleted for any reason', 'To support investigations, audits, and legal requirements', 'To replace system backups', 'To improve system performance over time', 'B', 'Archived logs may be needed to investigate breaches discovered months later or to meet retention rules. They must be protected from tampering.'),
  (249, 'secplus-governance', 'A document requires all laptops to use AES-256 full-disk encryption. What type of governance document is this?', 'A policy statement of intent', 'A memorandum of understanding', 'A standard', 'A guideline', 'C', 'Standards define specific, mandatory technical requirements that support policies. Guidelines are recommendations that aren''t mandatory.'),
  (250, 'secplus-audits-assessments', 'How does a vulnerability scan differ from a penetration test?', 'A scan finds weaknesses; a pen test exploits them', 'A pen test is fully automated, while a scan needs a human tester', 'They are the same activity', 'A scan always exploits vulnerabilities', 'A', 'Scans are automated and broad. Penetration tests are deeper, manual, and show real-world impact.'),
  (251, 'secplus-data-protection', 'Which control most directly protects data in transit between a browser and a web server?', 'Full-disk encryption', 'Data masking on reports', 'TLS encryption', 'Database backups', 'C', 'TLS encrypts data as it moves across the network. Full-disk encryption protects only data at rest on the device.'),
  (252, 'secplus-hardening', 'Before deploying a new wireless network, a technician walks the building measuring signal strength to plan access point placement. What is this?', 'A penetration test', 'War driving', 'A site survey', 'A tabletop exercise', 'C', 'A site survey finds coverage, interference, and the best access point locations. It also helps limit signal leaking outside the building.'),
  (253, 'secplus-incident-response', 'An infected server is disconnected from the network to stop malware from spreading. Which incident response phase is this?', 'Containment', 'Eradication', 'Recovery', 'Preparation', 'A', 'Containment limits the incident''s spread and damage. Eradication then removes the malware and closes the entry point.'),
  (254, 'secplus-resilience-recovery', 'A warm site is best described as:', 'A site with some equipment, but data must be restored first', 'An empty facility with only power, cooling, and network space', 'A set of backup tapes stored offsite', 'A fully synchronized duplicate of production', 'A', 'Warm sites balance cost and recovery time. They have hardware ready but need current data loaded and some setup.'),
  (255, 'secplus-enterprise-security', 'What is the purpose of firewall rules that end with an implicit deny?', 'The firewall turns off when idle', 'All traffic is allowed unless a rule specifically blocks it', 'Any traffic not explicitly allowed is blocked', 'Only encrypted traffic is logged', 'C', 'An implicit deny means only defined, needed traffic passes. It follows the principle of least privilege.'),
  (256, 'secplus-cryptography', 'A bank needs a tamper-resistant appliance to generate and store thousands of keys for its payment systems. Which should it use?', 'A Trusted Platform Module (TPM)', 'An OCSP responder', 'A hardware security module (HSM)', 'A certificate signing request', 'C', 'HSMs are dedicated devices built for secure, high-volume key generation and storage. A TPM protects keys for a single device and isn''t designed for enterprise key management.'),
  (257, 'secplus-threat-vectors', 'An attacker sends an image file with malicious code hidden in its metadata, aimed at exploiting the victim''s image viewer. Which threat vector is this?', 'Removable device', 'Voice call', 'Image-based', 'Wired network', 'C', 'Image-based vectors deliver malicious code inside image files or exploit flaws in image parsing. Keeping viewers patched reduces the risk.'),
  (258, 'secplus-vulnerabilities', 'A cloud provider''s shared API has a flaw that lets one customer access another customer''s data. Which type of vulnerability is this?', 'Cloud-specific', 'Removable media', 'Physical', 'Bluetooth', 'A', 'Multitenancy flaws, insecure APIs, and isolation failures are cloud-specific vulnerabilities. Customers depend on the provider to fix flaws in the shared platform.'),
  (259, 'secplus-architecture-models', 'What does software-defined networking (SDN) do?', 'Physically isolates networks so they have no connections', 'Encrypts all traffic between switches by default', 'Replaces routers with cloud-hosted firewalls', 'Separates the control and data planes for central management', 'D', 'SDN centralizes network control in software, which allows programmable, automated management. The controller then becomes a high-value target that must be secured.'),
  (260, 'secplus-risk-management', 'What is the purpose of a business impact analysis (BIA)?', 'To scan systems for vulnerabilities', 'To test firewall rule effectiveness', 'To audit the organization''s financial statements for accuracy', 'To identify critical functions and the impact of disruption', 'D', 'A BIA determines which functions matter most and sets RTOs and RPOs. It drives continuity and recovery priorities.'),
  (261, 'secplus-identity-access', 'A PAM tool stores administrative passwords, checks them out to approved users, and rotates them after each use. What is this feature?', 'Federation', 'Password vaulting', 'Attestation', 'Identity proofing', 'B', 'Password vaulting secures privileged credentials and controls who uses them. Rotation makes sure a checked-out password can''t be reused later.'),
  (262, 'secplus-malicious-activity', 'An attacker forces a client and server to negotiate an older, weaker version of TLS that can be broken. What is this?', 'A birthday attack', 'A downgrade attack', 'Pass the hash', 'A replay attack', 'B', 'Downgrade attacks push connections to weaker protocols or ciphers. Disabling old protocol versions on servers removes the option.'),
  (263, 'secplus-secure-infrastructure', 'A company hosts its public web and email servers in a network zone separated from both the internet and the internal LAN by firewalls. What is this zone called?', 'An intranet', 'A honeynet', 'A screened subnet (DMZ)', 'An air-gapped network', 'C', 'A screened subnet holds public-facing services so a compromise there doesn''t directly expose the internal network. Firewalls control traffic on both sides.'),
  (264, 'secplus-malicious-activity', 'An attacker captures a valid authentication token from network traffic and resends it later to gain access. What attack is this?', 'Typosquatting', 'A replay attack', 'A collision attack', 'A buffer overflow', 'B', 'Replay attacks reuse captured credentials or tokens. Timestamps, nonces, and session expiration make captured data useless.'),
  (265, 'secplus-secure-infrastructure', 'Which statement correctly describes a passive security device?', 'It forwards traffic between VLANs', 'It monitors copies of traffic and alerts, but can''t block', 'It must be installed on every endpoint', 'It sits inline in the traffic path and drops malicious packets', 'B', 'Passive devices, such as an IDS on a tap or SPAN port, observe without affecting traffic. Active, inline devices can block traffic.'),
  (266, 'secplus-identity-access', 'Instead of permanent admin rights, an engineer requests elevated access that is granted for two hours and then revoked automatically. What is this?', 'Federation', 'Password reuse', 'Discretionary access control', 'Just-in-time permissions', 'D', 'Just-in-time access limits how long privileges exist, which reduces the window for abuse. It''s a core feature of privileged access management.'),
  (267, 'secplus-cryptography', 'PBKDF2 and bcrypt make brute-force attacks slower by hashing a password many times. This technique is called:', 'Key stretching', 'Salting', 'Key escrow', 'Obfuscation', 'A', 'Key stretching repeats the hashing process to make each guess expensive. Both algorithms also use salts, but the repeated iterations are what stretching refers to.'),
  (268, 'secplus-threat-vectors', 'What makes spear phishing more effective than regular phishing?', 'It never contains links, so filters miss it', 'It''s sent to far more recipients at once, so more people are likely to click', 'It always arrives by voice call instead of email', 'It''s personalized using researched details about the target', 'D', 'Spear phishing uses personal details to look legitimate, which raises the chance the target trusts it. Mass, untargeted messages are regular phishing.'),
  (269, 'secplus-vulnerabilities', 'Attackers compromise a software vendor''s build server and insert malware into a legitimate update that customers install. What type of vulnerability is this?', 'A race condition in the installer', 'A misconfigured customer firewall', 'Default credentials on the update server', 'Software supply chain compromise', 'D', 'Supply chain attacks abuse trust in a vendor, so the malicious code arrives signed and expected. Verifying software integrity and monitoring vendors helps reduce the risk.'),
  (270, 'secplus-architecture-models', 'A medical device runs embedded firmware that the vendor no longer updates. What architecture concern does this highlight?', 'High responsiveness', 'Excess compute power', 'Inability to patch', 'Ease of deployment', 'C', 'Embedded and legacy devices often can''t be patched, so vulnerabilities persist. Compensating controls such as segmentation are needed.'),
  (271, 'secplus-risk-management', 'A risk assessment is done only for a single project, such as a one-off merger. What type of assessment is this?', 'One-time', 'Recurring', 'Continuous', 'Automated', 'A', 'One-time assessments address a specific event or project. Recurring assessments repeat on a schedule.'),
  (272, 'secplus-resilience-recovery', 'Which recovery site provides only space, power, and connectivity, with no equipment installed?', 'Hot site', 'Cold site', 'Cloud failover region', 'Warm site', 'B', 'A cold site is the cheapest option but takes the longest to bring online. Equipment must be brought in and configured, and data restored.'),
  (273, 'secplus-enterprise-security', 'Which protocol should replace Telnet for secure remote command-line administration?', 'HTTP on port 80', 'SSH on port 22', 'FTP on port 21', 'SNMPv1 on port 161', 'B', 'SSH encrypts the session, including credentials. Telnet sends everything in plaintext.'),
  (274, 'secplus-data-protection', 'What is the purpose of permission restrictions as a data protection method?', 'To keep data within certain countries', 'To make stored data unreadable without a key', 'To permanently remove data no longer needed', 'To limit access and changes to authorized users', 'D', 'Permissions enforce access control based on roles and least privilege. They complement encryption rather than replace it.'),
  (275, 'secplus-hardening', 'A browser runs each website''s code in an isolated environment so malicious code can''t access the operating system. What is this?', 'Load balancing', 'Sandboxing', 'Journaling', 'Tokenization', 'B', 'Sandboxing contains code in a restricted environment to limit damage. It''s widely used in browsers, mobile apps, and malware analysis.'),
  (276, 'secplus-incident-response', 'What is the goal of root cause analysis after an incident?', 'To determine which employee should be disciplined for the incident', 'To restore systems as quickly as possible', 'To find the underlying cause so it doesn''t recur', 'To estimate the cost of the incident', 'C', 'Fixing only symptoms lets incidents recur. Root cause analysis finds the real weakness, such as a missing patch or a gap in a process.'),
  (277, 'secplus-threat-actors', 'Which threat actor is most associated with ransomware campaigns run like a business for profit?', 'Nation-states seeking espionage', 'Organized crime', 'Hacktivists', 'Shadow IT users', 'B', 'Organized crime groups are motivated by money and often run ransomware as a professional operation. Hacktivists are driven by ideology, not profit.'),
  (278, 'secplus-mitigations', 'What is the purpose of a host-based intrusion prevention system (HIPS)?', 'To inspect all traffic crossing a network segment and block attacks there', 'To detect and block malicious activity on a single host', 'To issue certificates to endpoints', 'To filter spam before it reaches mailboxes', 'B', 'A HIPS watches processes, files, and system calls on an endpoint and stops malicious actions. It works on the host, not the network.'),
  (279, 'secplus-vulnerability-management', 'Which threat intelligence source consists of freely available public information?', 'Internal incident tickets', 'Classified government reports', 'Proprietary threat feeds', 'Open-source intelligence (OSINT)', 'D', 'OSINT comes from public sources such as websites, social media, and public vulnerability databases. Proprietary feeds are paid commercial services.'),
  (280, 'secplus-monitoring', 'Antivirus software that relies only on signatures has which limitation?', 'It may miss new or modified malware', 'It blocks all unsigned software', 'It never needs signature updates', 'It can''t detect any known malware', 'A', 'Signature-based detection catches known threats but struggles with new variants. Behavior-based and heuristic detection help fill the gap.'),
  (281, 'secplus-governance', 'Which policy defines how software is planned, built, tested, and maintained securely?', 'Change management (CM) policy', 'Data retention and disposal policy', 'Software development life cycle (SDLC) policy', 'Acceptable use policy (AUP)', 'C', 'An SDLC policy builds security into each phase of development. Fixing flaws early is far cheaper than after release.'),
  (282, 'secplus-audits-assessments', 'Testers receive no information about the target and must discover everything themselves, as a real outside attacker would. Which test type is this?', 'Known environment (white box)', 'Partially known environment', 'Unknown environment (black box)', 'Integrated testing', 'C', 'Black box testing is the most realistic view of an external attacker. It may miss issues that insider knowledge would reveal.'),
  (283, 'secplus-security-concepts', 'A network of decoy systems built to observe attacker behavior across multiple hosts is called a:', 'Jump server', 'Honeynet', 'Screened subnet', 'Honeyfile', 'B', 'A honeynet is a group of honeypots that simulates a real network. A screened subnet is a real DMZ for public-facing services, not a decoy.'),
  (284, 'secplus-security-controls', 'Which of the following is an example of a managerial security control?', 'A firewall rule that blocks inbound Telnet to all servers', 'An annual risk assessment of business systems', 'Full-disk encryption on company laptops', 'Bollards in front of the lobby entrance', 'B', 'Managerial controls are about planning and oversight: risk assessments, policies, and governance. Firewall rules and encryption are technical controls, and bollards are physical controls.'),
  (285, 'secplus-third-party-risk', 'What is due diligence in vendor selection?', 'Signing the contract without review', 'Choosing the lowest-cost vendor', 'Investigating a vendor before entering a relationship', 'Testing the vendor''s product only after a breach has occurred', 'C', 'Due diligence identifies risks before commitment. It typically includes questionnaires, audit reports, and reference checks.'),
  (286, 'secplus-compliance', 'Data retention policies for compliance should ensure that data is:', 'Kept indefinitely in case it''s ever needed', 'Kept only in printed form in locked storage', 'Deleted as soon as it''s no longer in use', 'Kept as long as required, then securely disposed of', 'D', 'Keeping data too briefly violates requirements, and keeping it too long increases risk and liability. Retention schedules balance both.'),
  (287, 'secplus-change-management', 'A change to a database server unexpectedly breaks a web application that relies on it. Which change management step would most likely have caught this?', 'Identifying dependencies during impact analysis', 'Updating network diagrams after the change', 'Scheduling the change during business hours', 'Notifying the help desk after go-live', 'A', 'Impact analysis identifies dependent systems that a change might affect. Updating documentation afterward is important, but it can''t prevent the outage.'),
  (288, 'secplus-investigation-data', 'An email header shows the message passed through a mail server in an unexpected country. Which data source is being examined?', 'A packet capture', 'A firewall rule base', 'An asset inventory', 'Metadata', 'D', 'Email header metadata traces the message''s route. Mismatches with the claimed sender point to spoofing.'),
  (289, 'secplus-asset-management', 'Before disposing of old hard drives that held confidential data, what should an organization do?', 'Delete the files and empty the recycle bin', 'Sanitize or physically destroy the drives', 'Remove the drives'' partition tables', 'Reformat the drives with a quick format', 'B', 'Deleting files or quick formatting leaves data recoverable. Proper sanitization, such as overwriting or cryptographic erase, or physical destruction is required.'),
  (290, 'secplus-automation', 'Automation scripts can add newly launched cloud servers to the correct security group as they start. What benefit does this demonstrate?', 'Removing the need for host firewalls', 'Scaling securely with consistent configurations', 'Reducing the number of security groups needed', 'Bypassing change management for servers', 'B', 'Automation applies standard security settings as resources scale up and down. Manual processes can''t keep pace with elastic cloud environments.'),
  (291, 'secplus-security-awareness', 'How can an organization measure the effectiveness of its security awareness program?', 'Surveying only the trainers', 'Measuring how long employees spend watching the training video', 'Counting the slides in the training', 'Tracking phishing click and reporting rates', 'D', 'Metrics show whether behavior is improving. A rising reporting rate and falling click rate indicate success.'),
  (292, 'secplus-malicious-activity', 'An attacker corrupts a DNS resolver''s cache so users trying to reach their bank are sent to a malicious IP address. What is this?', 'Typosquatting', 'DNS cache poisoning', 'Bluesnarfing', 'Domain hijacking', 'B', 'DNS poisoning inserts false records into a resolver''s cache, redirecting users even when they type the correct name. DNSSEC helps protect against it.'),
  (293, 'secplus-secure-infrastructure', 'Which technology requires a device to authenticate before it is granted access through a switch port?', 'NAT', 'IEEE 802.1X', 'VLAN trunking', 'Spanning Tree Protocol', 'B', '802.1X provides port-based network access control, usually with a RADIUS server and EAP. Unauthenticated devices stay blocked.'),
  (294, 'secplus-identity-access', 'A user enters a password and then a code from an authenticator app. Which factors are being used?', 'Something you know and something you are', 'Something you know and something you have', 'Something you have and somewhere you are', 'Two instances of something you know', 'B', 'The password is something you know, and the app on the phone is something you have. Two different factor types make this true multifactor authentication.'),
  (295, 'secplus-cryptography', 'Which statement about hashing is true?', 'Its output length grows with the size of the input', 'It is a one-way function that produces a fixed-length output', 'It can be reversed by anyone who holds the correct decryption key', 'It provides confidentiality for data in transit', 'B', 'A hash function always produces the same length output and can''t be reversed. Encryption, not hashing, provides confidentiality.'),
  (296, 'secplus-threat-vectors', 'A traveler connects to free coffee shop Wi-Fi with no encryption. Which threat vector does this expose them to?', 'Default device credentials', 'A watering hole website', 'An unsecure wireless network', 'A malicious software update', 'C', 'Open Wi-Fi allows eavesdropping and on-path attacks. Using a VPN on untrusted networks protects traffic from others on the network.'),
  (297, 'secplus-vulnerabilities', 'An attacker posts a comment containing a script on a forum, and the script runs in the browser of every user who views the page. What is this?', 'Stored cross-site scripting', 'Reflected cross-site scripting', 'Server-side request forgery', 'SQL injection', 'A', 'Stored, or persistent, XSS saves the malicious script on the server, so it runs for every visitor. Reflected XSS requires each victim to click a crafted link.'),
  (298, 'secplus-architecture-models', 'Which architecture consideration measures how quickly a system responds to user requests?', 'Power', 'Risk transference', 'Resilience', 'Responsiveness', 'D', 'Responsiveness is about performance and latency. Security controls like inspection and encryption can affect it, so designs must balance both.'),
  (299, 'secplus-risk-management', 'A company stops offering a risky service entirely to eliminate the associated risk. Which risk strategy is this?', 'Avoidance', 'Transference', 'Mitigation', 'Acceptance', 'A', 'Avoidance removes the risk by ending the activity. Mitigation keeps the activity but reduces the risk with controls.'),
  (300, 'secplus-resilience-recovery', 'What is the advantage of a full backup compared with incremental backups?', 'It takes the least time to create each day', 'It uses the least storage', 'It backs up only changed files', 'Restoring requires only one backup set', 'D', 'A full backup holds everything, so restoring is simple. Incremental backups are faster to create but need the last full backup plus every incremental to restore.'),
  (301, 'secplus-enterprise-security', 'What does endpoint detection and response (EDR) provide beyond traditional antivirus?', 'Behavioral detection with investigation and response tools', 'Signature-based scanning of every file downloaded to the endpoint', 'Filtering of inbound email attachments', 'Physical tracking of lost laptops', 'A', 'EDR records endpoint activity, detects suspicious behavior, and lets analysts investigate and isolate hosts. XDR extends this across network, cloud, and email.'),
  (302, 'secplus-data-protection', 'Which data type is protected by patents, copyrights, and trademarks?', 'Intellectual property', 'Regulated health data', 'Legal data', 'Public data', 'A', 'Intellectual property covers creations of the mind and is protected by law. Trade secrets are a form of IP kept confidential instead of registered.'),
  (303, 'secplus-hardening', 'A company buys phones, owns them, and lets employees use them for personal tasks too. Which model is this?', 'CYOD', 'COPE', 'BYOD', 'VDI', 'B', 'Corporate-owned, personally enabled devices give the company full control while allowing personal use. In CYOD, employees choose from approved models.'),
  (304, 'secplus-incident-response', 'Analysts proactively search the network for signs of attackers who may have evaded existing alerts. What is this?', 'Tabletop exercise', 'Threat hunting', 'Vulnerability scanning', 'Change management', 'B', 'Threat hunting assumes a breach and looks for hidden adversaries using hypotheses and intelligence. It doesn''t wait for alerts.'),
  (305, 'secplus-threat-actors', 'A group defaces a corporation''s website to protest its environmental record. What is the most likely motivation?', 'Espionage for a competitor', 'Revenge for a personal grievance', 'Financial gain through extortion', 'Philosophical or political beliefs', 'D', 'Hacktivists attack to promote a cause or ideology, often through defacement or DDoS. They aren''t typically seeking money.'),
  (306, 'secplus-mitigations', 'A laptop runs host-based firewall software that blocks unsolicited inbound connections. What does this provide?', 'Protection against physical theft', 'Encryption of data stored on the drive', 'Automatic backups of the system', 'Protection even on untrusted networks', 'D', 'A host-based firewall protects the device wherever it is, including on public Wi-Fi. It doesn''t encrypt data or prevent theft.'),
  (307, 'secplus-vulnerability-management', 'Which analysis tests a running application by sending inputs and observing its behavior?', 'Code signing', 'Dynamic analysis', 'Static analysis', 'Package monitoring', 'B', 'Dynamic analysis (DAST), including fuzzing, tests the live application. It finds runtime issues that static analysis can miss.'),
  (308, 'secplus-monitoring', 'Why are vulnerability scanners considered a monitoring tool?', 'They replace the need for perimeter firewalls', 'They encrypt data stored on scanned hosts', 'They find new weaknesses as systems and threats change', 'They block exploit attempts in real time across the whole network', 'C', 'Regular scanning monitors the environment''s security posture over time. New vulnerabilities are disclosed constantly.'),
  (309, 'secplus-governance', 'A board of directors forms a committee to oversee cybersecurity risk. What does this represent?', 'A penetration test', 'A governance structure', 'A technical control', 'A data processor', 'B', 'Boards and committees provide oversight and accountability for security. Governance aligns security with business goals.'),
  (310, 'secplus-audits-assessments', 'After a penetration test, what is the most important deliverable?', 'A public post of exploited data', 'The testers'' invoices and time sheets', 'A report of findings, risk ratings, and fixes', 'A list of every tool and script the testers used during the test', 'C', 'The report turns test results into action. Findings should be prioritized by risk so they can be fixed.'),
  (311, 'secplus-malicious-activity', 'A server''s security logs show a gap of several hours with no entries, while other servers logged normally. What could this indicate?', 'An attacker may have cleared the logs', 'No users were logged in during that time', 'The log retention policy is working as intended', 'The server''s antivirus was being updated', 'A', 'Missing logs are a classic indicator of compromise, because attackers often clear logs to hide activity. Sending logs to a central SIEM protects them from tampering.'),
  (312, 'secplus-secure-infrastructure', 'When selecting security controls for a new network segment, what should primarily drive the choice?', 'The controls used on the previous project', 'The lowest-cost product available', 'The vendor with the most features', 'The risks and data sensitivity of that segment', 'D', 'Effective controls address the specific risks and compliance needs of what''s being protected. Copying controls without analysis leaves gaps or wastes money.'),
  (313, 'secplus-security-concepts', 'Which practice best supports the zero trust principle of threat scope reduction?', 'Trusting devices once they join the internal network', 'Using one flat network to simplify monitoring', 'Granting broad standing access to reduce help desk tickets', 'Granting least privilege and microsegmenting access', 'D', 'Threat scope reduction limits the blast radius of a compromise through least privilege and microsegmentation. A flat, trusted network lets an attacker move freely once inside.'),
  (314, 'secplus-identity-access', 'Payroll changes are allowed only Monday through Friday, 8 a.m. to 6 p.m. Which access control is this?', 'Federation', 'Biometrics', 'Mandatory access control', 'Time-of-day restrictions', 'D', 'Time-of-day restrictions limit when accounts can be used, which reduces the window for misuse. They''re often combined with other controls.'),
  (315, 'secplus-cryptography', 'A help desk screen shows only the last four digits of a customer''s Social Security number. This is an example of:', 'Data masking', 'Salting', 'Key stretching', 'Tokenization', 'A', 'Masking hides part of the data from view while leaving enough to be useful. Tokenization would replace the whole value with a surrogate.'),
  (316, 'secplus-threat-vectors', 'A fake website copies a well-known bank''s logo, colors, and layout to collect login credentials. Which technique is this?', 'Pretexting', 'Typosquatting', 'Bluesnarfing', 'Brand impersonation', 'D', 'Brand impersonation mimics a trusted company''s look to deceive users. It''s often combined with typosquatting, but the key here is the copied branding.'),
  (317, 'secplus-vulnerabilities', 'A cloud storage bucket holding customer records is left publicly readable. What type of vulnerability is this?', 'Zero-day', 'Firmware vulnerability', 'Buffer overflow', 'Misconfiguration', 'D', 'Insecure configuration, such as public buckets or open permissions, is one of the most common causes of cloud breaches. It''s a setup error, not a software flaw.'),
  (318, 'secplus-architecture-models', 'Which statement about a public cloud provider''s responsibility matrix is correct?', 'It lists the provider''s compliance certifications', 'It applies only to on-premises data centers', 'It transfers all security duties, including data protection, to the provider', 'It shows which security tasks belong to the provider and the customer', 'D', 'A responsibility matrix maps duties by service model. Misunderstanding it, for example assuming the provider secures your data configuration, causes many cloud breaches.'),
  (319, 'secplus-risk-management', 'A company buys cybersecurity insurance to cover losses from a data breach. Which risk strategy is this?', 'Acceptance', 'Avoidance', 'Mitigation', 'Transference', 'D', 'Insurance transfers the financial impact to a third party. The organization is still responsible for protecting data.'),
  (320, 'secplus-security-controls', 'An intrusion prevention system drops malicious packets as they arrive. Which combination best describes this control?', 'Physical and detective', 'Operational and preventive', 'Technical and corrective', 'Technical and preventive', 'D', 'An IPS is a technology (technical) that blocks attacks before they reach the target (preventive). An IDS that only alerts would be detective.'),
  (321, 'secplus-third-party-risk', 'A company reviews a cloud provider''s SOC 2 Type II report before signing a contract. What is the company doing?', 'Performing its own penetration test against the vendor''s systems', 'Reviewing an independent assessment as due diligence', 'Creating the company''s own risk register', 'Writing a service level agreement', 'B', 'Independent audit reports show a vendor''s controls were tested by a third party. Type II covers how controls operated over a period of time.'),
  (322, 'secplus-compliance', 'Employees must annually sign that they have read and understand the security policy. What is this?', 'Acknowledgement (attestation)', 'Federation', 'Data masking', 'Penetration testing', 'A', 'Signed acknowledgement documents that users know the rules. It supports accountability and compliance.'),
  (323, 'secplus-resilience-recovery', 'Why does an organization place its backup data center in a different region from its primary site?', 'To lower the cost of encrypting backups', 'So one regional disaster can''t affect both sites', 'To speed up network traffic for local users', 'To meet the RTO for local hardware failures', 'B', 'Geographic dispersion protects against regional disasters. Sites too close together can be hit by the same event.'),
  (324, 'secplus-enterprise-security', 'Which email authentication method lists the mail servers allowed to send email for a domain?', 'S/MIME', 'DMARC', 'DKIM', 'SPF', 'D', 'Sender Policy Framework publishes authorized sending servers in DNS. DKIM signs messages, and DMARC sets policy using both.'),
  (325, 'secplus-change-management', 'Which practice tracks revisions to configuration files and lets administrators roll back to a previous state?', 'Load balancing', 'Tokenization', 'Data masking', 'Version control', 'D', 'Version control records each change, who made it, and when, and lets you revert to earlier versions. Masking and tokenization protect data; they don''t track changes.'),
  (326, 'secplus-malicious-activity', 'Which attack exploits the probability of two different inputs producing the same hash value?', 'A replay attack', 'Password spraying', 'A birthday attack', 'A downgrade attack', 'C', 'The birthday paradox makes hash collisions far more likely than intuition suggests, which is why longer hash outputs are needed. A downgrade attack targets protocol negotiation instead.'),
  (327, 'secplus-secure-infrastructure', 'Which statement about TLS-based VPNs compared with IPsec VPNs is generally true?', 'They often work in a browser and pass firewalls on port 443', 'They can''t encrypt traffic and can only authenticate users to the network', 'They require a dedicated leased line', 'IPsec can only be used for remote access', 'A', 'TLS VPNs use HTTPS ports, which are rarely blocked, and can be clientless. IPsec is common for both site-to-site and remote access.'),
  (328, 'secplus-data-protection', 'Which classification fits a press release that has been approved for publication?', 'Public', 'Restricted', 'Confidential', 'Critical', 'A', 'Public data can be freely shared and causes no harm if disclosed. Confidential and restricted data require protection.'),
  (329, 'secplus-hardening', 'Why are IoT devices often more difficult to harden than workstations?', 'They have few settings and rarely get firmware updates', 'They can''t be placed on a separate network', 'They ship with strong security by default', 'They run full desktop operating systems that need frequent reboots', 'A', 'Many IoT devices offer few security settings and rarely get updates. Network segmentation is often the main protection.'),
  (330, 'secplus-incident-response', 'A simulation in which the team responds to a realistic mock attack using actual systems and tools is called:', 'A simulation exercise', 'A document review', 'A tabletop exercise', 'Lessons learned', 'A', 'Simulations test real responses in practice, which is more realistic than a tabletop discussion. They can reveal tool and process gaps.'),
  (331, 'secplus-investigation-data', 'Which network log would help determine which internal IP address a device was assigned at a specific time?', 'Badge reader logs', 'Antivirus logs', 'DHCP logs', 'Application logs', 'C', 'DHCP logs map IP addresses to MAC addresses and lease times. That''s essential when IPs change over time.'),
  (332, 'secplus-identity-access', 'Which of the following is an example of something you are?', 'A hardware token', 'A PIN', 'A fingerprint scan', 'A smart card', 'C', 'Biometrics such as fingerprints or face scans are inherence factors. A PIN is knowledge, and cards and tokens are possession.'),
  (333, 'secplus-threat-actors', 'During a geopolitical conflict, attackers disable a country''s power grid controls. Which motivation best fits?', 'Ethical', 'War', 'Financial gain', 'Blackmail', 'B', 'Attacks on critical infrastructure to support a military or political conflict are acts of cyberwarfare. Such attacks usually aren''t motivated by money.'),
  (334, 'secplus-mitigations', 'During setup of a new router, what is one of the first hardening steps?', 'Change the default administrator password', 'Enable remote administration from the internet', 'Turn off firmware updates', 'Leave Telnet enabled for convenience', 'A', 'Default passwords are widely published, so attackers try them first. Changing them right away closes an easy entry point.'),
  (335, 'secplus-vulnerability-management', 'A vulnerability scan reports a flaw that, on investigation, doesn''t actually exist on the system. What is this?', 'A zero-day', 'A false negative', 'A false positive', 'A true positive', 'C', 'A false positive is a reported issue that isn''t real. False negatives are more dangerous, because real vulnerabilities go unreported.'),
  (336, 'secplus-monitoring', 'What is the primary function of a SIEM?', 'Encrypting log data stored at rest', 'Collecting and correlating logs to detect security events', 'Blocking malicious traffic inline at the perimeter', 'Scanning hosts for missing patches', 'B', 'A SIEM aggregates logs, correlates events across systems, and raises alerts. It gives a central view for detection and investigation.'),
  (337, 'secplus-governance', 'Under GDPR, which entity determines the purposes and means of processing personal data?', 'The data custodian', 'The data processor', 'The data subject', 'The data controller', 'D', 'The controller decides why and how personal data is processed. The processor handles data on the controller''s behalf, such as a payroll vendor.'),
  (338, 'secplus-audits-assessments', 'A tester attempts to enter a building by tailgating employees and bypassing locks. What type of penetration test is this?', 'Code review', 'Web application test', 'Wireless test', 'Physical penetration test', 'D', 'Physical tests check controls such as locks, guards, and badge systems. Social engineering is often part of them.'),
  (339, 'secplus-cryptography', 'What is the main advantage of symmetric encryption over asymmetric encryption?', 'It is much faster for encrypting large amounts of data', 'It uses separate keys to encrypt and decrypt', 'It provides non-repudiation', 'It solves the problem of distributing keys securely to many users', 'A', 'Symmetric algorithms are far more efficient, which is why TLS uses them for bulk data. Key distribution is symmetric encryption''s weakness, which asymmetric methods solve.'),
  (340, 'secplus-threat-vectors', 'Attackers compromise a managed service provider and use its remote management tools to reach the MSP''s clients. What type of threat vector is this?', 'Image-based', 'Supply chain', 'Typosquatting', 'Removable device', 'B', 'MSPs are part of the supply chain, and their privileged access to customers makes them attractive targets. Vendor risk assessments and least privilege for third parties help reduce this risk.'),
  (341, 'secplus-vulnerabilities', 'A web application lets users request files with a parameter like ../../etc/passwd to read files outside the web root. What is this vulnerability?', 'Buffer overflow', 'Stored XSS', 'Directory traversal', 'SQL injection', 'C', 'Directory, or path, traversal uses ../ sequences to escape the intended directory. Validating and normalizing file paths prevents it.'),
  (342, 'secplus-architecture-models', 'An automotive braking controller must respond within strict time limits. What type of operating system does it most likely use?', 'A general-purpose desktop OS', 'A container orchestrator', 'A real-time operating system (RTOS)', 'A serverless runtime', 'C', 'An RTOS guarantees responses within strict deadlines. These systems are often embedded and hard to patch, which raises security concerns.'),
  (343, 'secplus-risk-management', 'What does mean time to repair (MTTR) measure?', 'The average time a system runs between one failure and the next', 'The annual expected cost of a risk', 'The average time to repair and restore service', 'The maximum data loss allowed', 'C', 'Lower MTTR means faster recovery. Spare parts and good procedures reduce it.'),
  (344, 'secplus-asset-management', 'What does assigning an owner to each asset accomplish?', 'Transfer of legal liability for the asset to its vendor', 'Removal of the asset from the inventory', 'Automatic encryption of the asset''s data', 'Accountability for the asset''s security and data', 'D', 'Owners are responsible for classification, access decisions, and risk acceptance for their assets. Without an owner, no one is accountable for its security.'),
  (345, 'secplus-automation', 'Why is automation described as a workforce multiplier for security teams?', 'It handles repetitive tasks so analysts can focus', 'It eliminates false positives entirely', 'It removes the need to hire and train new security analysts', 'It replaces written security policies', 'A', 'Automating routine tasks lets a small team do more. It also reduces burnout, which helps with employee retention.'),
  (346, 'secplus-security-awareness', 'An employee notices a coworker copying large amounts of data to a personal USB drive late at night. What does awareness training encourage them to do?', 'Copy the data themselves', 'Ignore it because it''s none of their business', 'Report the anomalous behavior through the proper channel', 'Confront the coworker directly and ask them to stop immediately', 'C', 'Recognizing and reporting unusual behavior helps catch insider threats early. Training should explain how and where to report.'),
  (347, 'secplus-security-concepts', 'Which of the following is an example of authorization rather than authentication?', 'A user''s role permits reading, but not editing, payroll', 'A user scans a fingerprint at the login screen', 'A user enters a password and then a one-time code from an app', 'A user taps a smart card on a reader at login', 'A', 'Authorization determines what an authenticated user may do, such as role-based permissions. Passwords, fingerprints, and smart cards all prove identity, which is authentication.'),
  (348, 'secplus-resilience-recovery', 'What is a VM snapshot most useful for?', 'Quickly reverting to a known state, such as before an update', 'Encrypting the VM''s data in transit', 'Replacing offsite backups for long-term retention of the VM''s data', 'Moving the VM between hosts without downtime', 'A', 'Snapshots capture a point-in-time state for fast rollback. They usually live on the same storage, so they don''t replace offsite backups.'),
  (349, 'secplus-enterprise-security', 'What does SELinux provide on Linux systems?', 'Encryption for wireless connections', 'Filtering of inbound email', 'Mandatory access control for processes', 'A graphical desktop environment', 'C', 'SELinux enforces strict policies even on processes running as root, limiting damage if a service is compromised. Standard Linux permissions are discretionary.'),
  (350, 'secplus-malicious-activity', 'A user''s account shows active sessions on two different computers in different buildings at the same time. What indicator is this?', 'Published vulnerability', 'Resource inaccessibility', 'Concurrent session usage', 'Out-of-cycle logging', 'C', 'Simultaneous sessions from different locations suggest the credentials have been stolen. Many systems limit or alert on concurrent sessions.'),
  (351, 'secplus-secure-infrastructure', 'Which firewall operates only on IP addresses, ports, and protocols, without inspecting application content?', 'A next-generation firewall', 'A layer 4 firewall', 'A web application firewall', 'A layer 7 firewall', 'B', 'Layer 4 firewalls make decisions on transport-layer information. Layer 7 firewalls inspect application data, such as HTTP requests.'),
  (352, 'secplus-identity-access', 'Which access control model lets the resource owner decide who can access their files?', 'Role-based access control (RBAC)', 'Discretionary access control (DAC)', 'Mandatory access control (MAC)', 'Rule-based access control', 'B', 'In DAC, owners grant permissions at their discretion, as with typical file sharing. MAC uses labels and clearances that users can''t change.'),
  (353, 'secplus-data-protection', 'A company stores its most sensitive data on a separate network segment with its own access controls. Which method is this?', 'Segmentation', 'Hashing', 'Masking', 'Obfuscation', 'A', 'Segmentation isolates sensitive data so a breach elsewhere can''t easily reach it. It also narrows the scope of compliance audits, such as for PCI DSS.'),
  (354, 'secplus-hardening', 'Why is input validation a critical application security practice?', 'It encrypts form data as it is submitted from the user''s browser', 'It replaces the need for authentication', 'It speeds up processing of database queries', 'It rejects malicious input before it can cause injection', 'D', 'Validating input on the server blocks many attacks, including SQL injection and XSS. Client-side validation alone can be bypassed.'),
  (355, 'secplus-incident-response', 'What is the purpose of chain of custody in digital forensics?', 'To identify the attacker''s location', 'To document who handled evidence and when', 'To speed up system recovery', 'To encrypt evidence while it''s stored', 'B', 'Chain of custody records every transfer of evidence. Gaps can make evidence inadmissible in court.'),
  (356, 'secplus-security-controls', 'Motion-activated cameras record activity in a server room hallway. How are they best classified?', 'Managerial and preventive', 'Physical and detective', 'Operational and directive', 'Technical and corrective', 'B', 'Cameras are physical security devices whose main purpose is to identify and record activity, making them detective. They may deter some intruders, but they don''t block anyone.'),
  (357, 'secplus-third-party-risk', 'Which agreement protects confidential information shared with a vendor during a project?', 'Service level agreement', 'Non-disclosure agreement (NDA)', 'Work order', 'Memorandum of understanding', 'B', 'NDAs legally bind parties to keep shared information confidential. They''re common before sharing sensitive details with vendors.'),
  (358, 'secplus-compliance', 'Which privacy regulation applies to the personal data of individuals in the European Union, regardless of where the company is located?', 'SOX', 'FERPA', 'GDPR', 'HIPAA', 'C', 'GDPR applies to EU personal data wherever it''s processed. HIPAA covers U.S. health information.'),
  (359, 'secplus-cryptography', 'Which protocol lets a browser check the revocation status of a single certificate in real time without downloading a full list?', 'Key escrow', 'CSR', 'CRL', 'OCSP', 'D', 'The Online Certificate Status Protocol returns the status of one certificate on request. A CRL is the full list of revoked certificates, which the client must download.'),
  (360, 'secplus-threat-vectors', 'A malicious document attached to an email runs a macro that downloads malware when opened. Which threat vector is this?', 'Default credentials', 'Wired network', 'File-based', 'Voice call', 'C', 'File-based vectors embed malicious code in documents, PDFs, or archives. Disabling macros from the internet blocks this common technique.'),
  (361, 'secplus-vulnerabilities', 'Which practice best reduces the risk of SQL injection?', 'Using parameterized queries', 'Increasing the database server''s memory', 'Encrypting the database at rest', 'Disabling the database''s audit logs', 'A', 'Parameterized queries treat input strictly as data, not executable SQL. Encryption at rest doesn''t stop an attacker who abuses the application''s own queries.'),
  (362, 'secplus-architecture-models', 'Which architecture consideration describes a system''s ability to handle growing workloads by adding resources?', 'Scalability', 'Ease of recovery', 'Risk transference', 'Patch availability', 'A', 'Scalability is adding capacity as demand grows, a major benefit of cloud. Ease of recovery is how quickly a system can be restored after failure.'),
  (363, 'secplus-risk-management', 'What does mean time between failures (MTBF) measure?', 'The maximum tolerable downtime', 'The average time a system operates before it fails', 'The average time it takes to repair a system after it has failed', 'The cost of a single failure', 'B', 'MTBF indicates reliability: higher is better. MTTR measures how long repairs take.'),
  (364, 'secplus-threat-actors', 'A well-funded group spends months quietly inside a defense contractor''s network, stealing weapons designs for a foreign government. Which threat actor is most likely responsible?', 'Unskilled attacker', 'Shadow IT', 'Nation-state', 'Hacktivist', 'C', 'Long-term, stealthy espionage with significant resources is the hallmark of nation-state actors, often called advanced persistent threats. Unskilled attackers lack the resources and patience for this kind of campaign.'),
  (365, 'secplus-mitigations', 'A hospital places its medical devices on a separate VLAN with firewall rules limiting what they can talk to. Which mitigation is this?', 'Data masking', 'Decommissioning', 'Segmentation', 'Tokenization', 'C', 'Segmentation contains threats by limiting communication between parts of the network. A compromised device can''t reach systems outside its segment.'),
  (366, 'secplus-vulnerability-management', 'What is the benefit of joining an information sharing and analysis center (ISAC)?', 'Receiving discounted security products', 'Outsourcing incident response to members', 'Exemption from compliance requirements', 'Sharing threat intelligence within an industry', 'D', 'ISACs let members of an industry, such as finance or healthcare, share threats and best practices. Shared intelligence helps everyone respond faster.'),
  (367, 'secplus-monitoring', 'Monitoring applications, as opposed to infrastructure, includes watching for which of the following?', 'Link status on each switch port', 'CPU temperature and fan speed on hosts', 'Power supply and UPS battery status', 'Unusual errors, failed logins, and odd transactions', 'D', 'Application monitoring finds attacks like credential stuffing or injection attempts in application logs. Infrastructure monitoring covers hardware and network health.'),
  (368, 'secplus-governance', 'Which external consideration requires a healthcare provider in the United States to protect patient records?', 'An internal guideline', 'A vendor''s marketing materials', 'Regulatory requirements such as HIPAA', 'An employee preference', 'C', 'Laws and regulations impose mandatory requirements on certain industries. Governance must account for local, national, and global rules.'),
  (369, 'secplus-audits-assessments', 'A tester runs port scans against the target''s servers to find open services. What is this?', 'Open-source intelligence only', 'Passive reconnaissance', 'A tabletop exercise', 'Active reconnaissance', 'D', 'Active reconnaissance interacts directly with targets and can be detected by IDS. Passive methods avoid direct contact.'),
  (370, 'secplus-malicious-activity', 'Users report their files now have a .locked extension, and a note demands cryptocurrency for a decryption key. What malware is this?', 'Ransomware', 'Adware', 'A logic bomb', 'Spyware', 'A', 'Ransomware encrypts files and demands payment to restore access. Offline, tested backups are the most important recovery control.'),
  (371, 'secplus-secure-infrastructure', 'A company wants to connect many branch offices by intelligently routing traffic over a mix of broadband, LTE, and MPLS links. Which technology fits best?', '802.1X', 'A jump server', 'An air gap', 'SD-WAN', 'D', 'Software-defined WAN centrally manages traffic across multiple connection types. SASE builds on it by adding cloud-delivered security.'),
  (372, 'secplus-resilience-recovery', 'A database records every transaction in a log so it can be replayed to recover to a specific point in time. What technique is this?', 'Load balancing', 'Journaling', 'Snapshotting', 'Tokenization', 'B', 'Journaling logs changes so a system can roll forward or back to a consistent state. It supports point-in-time recovery.'),
  (373, 'secplus-enterprise-security', 'Which secure protocol should replace FTP for transferring files?', 'HTTP', 'Telnet', 'TFTP', 'SFTP or FTPS', 'D', 'SFTP (over SSH) and FTPS (FTP over TLS) encrypt file transfers. TFTP has no authentication or encryption.'),
  (374, 'secplus-change-management', 'Which document defines the steps staff follow to perform a routine, pre-approved change?', 'A business impact analysis', 'A risk register', 'A memorandum of understanding', 'A standard operating procedure', 'D', 'Standard operating procedures give repeatable steps for routine tasks, including standard changes. A risk register tracks risks; it doesn''t describe how to do work.'),
  (375, 'secplus-investigation-data', 'A web server log shows hundreds of requests containing UNION SELECT from one IP address. Which log revealed this?', 'Physical access logs', 'Endpoint logs', 'Application logs', 'Firewall logs', 'C', 'Application logs, such as web server logs, record requests and errors. Here they reveal SQL injection attempts.'),
  (376, 'secplus-identity-access', 'A photo printing app asks for permission to access a user''s cloud photos without getting their password. Which standard makes this possible?', 'OAuth', 'LDAP', 'SAML', 'RADIUS', 'A', 'OAuth grants limited, token-based access to resources on the user''s behalf. The third-party app never sees the user''s password.'),
  (377, 'secplus-security-concepts', 'Which zero trust component sits in the data plane and allows, monitors, and terminates connections between a subject and a resource?', 'Policy administrator', 'Policy engine', 'Adaptive identity', 'Policy enforcement point', 'D', 'The policy enforcement point is the gatekeeper in the data plane. The policy engine and policy administrator are control plane components that decide on and set up access.'),
  (378, 'secplus-data-protection', 'A company classifies a system that processes all customer orders as critical. What does this classification indicate?', 'It must be deleted at the end of each day', 'It can be shared publicly without restriction', 'It''s essential to operations and needs high availability', 'It has low business value and needs only minimal protection', 'C', 'Critical data is vital to the business, so loss of availability or integrity would cause major harm. It drives backup and resilience priorities.'),
  (379, 'secplus-hardening', 'What does code signing provide?', 'Encryption of the source code', 'Proof of the publisher and that code wasn''t altered', 'Protection of the code from being copied', 'Proof that the code has been tested and contains no vulnerabilities', 'B', 'A digital signature verifies the publisher and the code''s integrity. Signed code can still contain bugs, so signing doesn''t guarantee it''s secure.'),
  (380, 'secplus-incident-response', 'When collecting digital evidence, which should be captured first according to the order of volatility?', 'CPU registers and RAM contents', 'Archived backup tapes', 'Remote logs stored on the SIEM', 'Hard drive contents', 'A', 'The most volatile data, which disappears when power is lost, is collected first. Disk data persists longer, and backups are least volatile.'),
  (381, 'secplus-cryptography', 'Which statement best describes key escrow?', 'A trusted third party holds copies of encryption keys so they can be recovered', 'Generating keys inside a TPM', 'A technique that strengthens weak passwords by hashing them many times over', 'A list of certificates that are no longer valid', 'A', 'Key escrow stores keys with a trusted party so encrypted data can be recovered if a key is lost. Repeated hashing is key stretching.'),
  (382, 'secplus-threat-vectors', 'Attackers compromise a website frequently visited by employees of a target industry so that visitors are infected. What is this called?', 'A spear phishing email', 'A pretexting phone call', 'A watering hole attack', 'A typosquatting campaign', 'C', 'In a watering hole attack, the attacker infects a site the targets already trust and visit. Typosquatting relies on users mistyping a domain.'),
  (383, 'secplus-vulnerabilities', 'An attacker exploits a flaw in a device''s firmware, which persists even after the operating system is reinstalled. What type of vulnerability is this?', 'Cloud-specific', 'Social engineering', 'Hardware or firmware', 'Web-based', 'C', 'Firmware runs below the OS, so compromises there survive reinstalls and are hard to detect. Secure boot and signed firmware updates help protect against this.'),
  (384, 'secplus-architecture-models', 'Logical segmentation of a network is most commonly done with:', 'VLANs and firewall rules', 'Removable media for transfers', 'Air gaps between networks', 'Separate buildings for each team', 'A', 'Logical segmentation divides one physical network into isolated parts using VLANs, subnets, and ACLs. Air gapping is physical isolation.'),
  (385, 'secplus-risk-management', 'What is the formula for single loss expectancy (SLE)?', 'Asset value x annualized rate of occurrence', 'Annualized loss expectancy / exposure factor', 'Asset value x exposure factor', 'Annualized loss expectancy x ARO', 'C', 'SLE is the expected loss from one occurrence of a risk. ALE then multiplies SLE by the annualized rate of occurrence.'),
  (386, 'secplus-malicious-activity', 'A free game a user downloaded also secretly opens a backdoor for remote attackers. What is this malware?', 'Bloatware', 'A worm', 'A keylogger', 'A trojan', 'D', 'A trojan disguises itself as legitimate software to trick users into installing it. Unlike a worm, it doesn''t spread on its own.'),
  (387, 'secplus-secure-infrastructure', 'Which EAP type requires certificates on both the client and the server, providing strong mutual authentication?', 'EAP-TLS', 'PEAP with passwords only', 'LEAP', 'EAP-MD5', 'A', 'EAP-TLS uses certificates on both sides, which makes it one of the strongest options. PEAP typically needs only a server certificate and uses passwords for clients.'),
  (388, 'secplus-security-controls', 'Which of the following is a detective control?', 'Restoring files from last night''s backup', 'Installing a fence around the parking lot', 'Reviewing system logs for repeated failed logins', 'Requiring employees to badge in before entering the data center', 'C', 'Log review identifies suspicious activity that has already occurred, which is the job of a detective control. Badges and fences are preventive, and restoring files is corrective.'),
  (389, 'secplus-threat-actors', 'An attacker with little technical knowledge downloads a ready-made exploit tool and runs it against random websites. This attacker is best described as:', 'An insider threat', 'An unskilled attacker', 'An organized crime group', 'A nation-state actor', 'B', 'Unskilled attackers, sometimes called script kiddies, use tools written by others without understanding them. Their attacks are usually opportunistic rather than targeted.'),
  (390, 'secplus-mitigations', 'Which mitigation allows only approved programs to run on a workstation?', 'Full-disk encryption', 'Data loss prevention', 'Application allow listing', 'Antivirus deny listing', 'C', 'An allow list blocks anything not explicitly approved, including unknown malware. Deny lists only block known-bad software.'),
  (391, 'secplus-resilience-recovery', 'Which recovery site has hardware, software, and current data ready, allowing operations to switch over within minutes to hours?', 'Warm site', 'Cold site', 'Hot site', 'Mobile site', 'C', 'A hot site is fully equipped and synchronized, which gives the fastest recovery at the highest cost. A cold site has only space and power.'),
  (392, 'secplus-asset-management', 'Which sanitization method makes data on a self-encrypting drive unrecoverable by destroying the encryption key?', 'Degaussing', 'Quick format', 'Defragmenting', 'Cryptographic erase', 'D', 'Cryptographic erase deletes the key, leaving the encrypted data unreadable. It''s fast and effective for drives that encrypt everything they store.'),
  (393, 'secplus-vulnerability-management', 'What is a CVE?', 'A standard for configuration benchmarks', 'A database of vendor patches and fixes', 'A unique identifier for a publicly known vulnerability', 'A score that rates each vulnerability''s severity from 0 to 10', 'C', 'CVE identifiers, such as CVE-2024-12345, let everyone refer to the same vulnerability. CVSS scores how severe it is.'),
  (394, 'secplus-monitoring', 'Why are security dashboards and automated reports valuable?', 'They prevent attacks automatically based on the trends they show', 'They encrypt the data they display', 'They summarize trends for quick decisions', 'They replace the need to keep logs', 'C', 'Dashboards and reports turn raw data into actionable views. They help track metrics and spot changes over time.'),
  (395, 'secplus-enterprise-security', 'How does extended detection and response (XDR) differ from EDR?', 'XDR removes the need to install any agents on endpoints', 'XDR is a firewall rule set for endpoints', 'XDR correlates endpoint, network, cloud, and email data', 'XDR protects only mobile devices', 'C', 'XDR broadens detection by combining telemetry from many layers. EDR focuses on endpoints.'),
  (396, 'secplus-identity-access', 'New nurses automatically receive access to patient charts because of their job title. Which access model is this?', 'Time-of-day restrictions', 'Role-based access control (RBAC)', 'Discretionary access control', 'Mandatory access control', 'B', 'RBAC assigns permissions to roles, and users get them by role membership. That simplifies managing many users with the same job.'),
  (397, 'secplus-automation', 'Which statement about using APIs for security automation is correct?', 'They are only used by public websites', 'They prevent tools from communicating', 'They let tools share data so workflows run automatically', 'They remove the need for authentication between connected tools', 'C', 'Integrations through APIs let a SIEM, EDR, and ticketing system act together. The APIs themselves must be secured with authentication.'),
  (398, 'secplus-governance', 'Which governance document offers recommended, but not mandatory, best practices?', 'A regulation', 'A standard', 'A policy', 'A guideline', 'D', 'Guidelines advise and leave room for judgment. Standards and policies are mandatory.'),
  (399, 'secplus-third-party-risk', 'Why should an organization analyze its vendors'' supply chains?', 'Supply chains don''t affect security', 'To avoid signing vendor contracts', 'To reduce the number of employees needed to manage vendor contracts', 'Risk from a vendor''s suppliers can affect the organization', 'D', 'Third-party risk includes fourth parties, the vendor''s own suppliers. Supply chain attacks exploit these indirect relationships.'),
  (400, 'secplus-compliance', 'What is a possible consequence of failing to comply with PCI DSS?', 'Fines and loss of card processing privileges', 'Lower cyber insurance premiums', 'Automatic certification for one year after the failed assessment', 'Free audits from the card brands', 'A', 'Card brands can impose fines or revoke card processing privileges. Noncompliance can also cause reputational damage.'),
  (401, 'secplus-audits-assessments', 'In the context of audits, what is attestation?', 'A review of firewall rules by the network team', 'A formal statement that controls meet requirements', 'A password reset process for audit accounts', 'A type of malware analysis used by auditors', 'B', 'Attestation provides formal assurance about compliance or control effectiveness. SOC reports are a common example.'),
  (402, 'secplus-security-awareness', 'Which training topic helps employees avoid accidentally causing incidents, such as emailing data to the wrong recipient?', 'Recognizing unintentional risky behavior', 'Configuring BGP routing', 'Advanced malware reverse engineering', 'Firewall rule optimization', 'A', 'Many incidents come from mistakes, not malice. Training on careful handling of data reduces unintentional insider risk.'),
  (403, 'secplus-malicious-activity', 'An attacker positions themselves between a user and a website, intercepting and possibly altering traffic. What is this attack called?', 'Credential stuffing', 'An on-path attack', 'Password spraying', 'A logic bomb', 'B', 'In an on-path (formerly man-in-the-middle) attack, the attacker relays traffic between two parties. Strong encryption and certificate validation defend against it.'),
  (404, 'secplus-secure-infrastructure', 'Why should management interfaces for network devices be placed on a separate, restricted network?', 'To limit who can reach and reconfigure network devices', 'To let vendors manage devices freely without going through the help desk', 'To increase bandwidth for user traffic', 'To avoid needing device authentication', 'A', 'A dedicated management network reduces exposure of administrative interfaces to attackers on user networks. Out-of-band management also works during outages.'),
  (405, 'secplus-cryptography', 'An administrator needs one certificate that covers www.example.com, mail.example.com, and shop.example.com. Which is the most efficient choice?', 'A separate self-signed certificate for each server', 'A root CA certificate', 'A code signing certificate', 'A wildcard certificate for *.example.com', 'D', 'A wildcard certificate covers all first-level subdomains of a domain. Self-signed certificates would trigger browser warnings, and code signing certificates aren''t for TLS.'),
  (406, 'secplus-threat-vectors', 'An attacker sends a phishing email tailored specifically to a company''s CEO, referencing an upcoming board meeting. What type of attack is this?', 'Smishing', 'Whaling', 'Vishing', 'Watering hole', 'B', 'Whaling is spear phishing aimed at high-value executives. The personalized detail makes the message more convincing.'),
  (407, 'secplus-vulnerabilities', 'Which practice best reduces the risk of cross-site scripting?', 'Hashing user passwords with a salt', 'Validating input and encoding output', 'Using longer keys for TLS certificates', 'Encrypting the database at rest', 'B', 'Output encoding makes the browser treat injected content as text instead of code, and input validation blocks malicious payloads. TLS protects data in transit but doesn''t stop XSS.'),
  (408, 'secplus-architecture-models', 'Under the shared responsibility model for IaaS, who is typically responsible for patching the guest operating system on a virtual machine?', 'The cloud provider', 'The internet service provider', 'The customer', 'The hypervisor vendor only', 'C', 'In IaaS, the provider secures the physical infrastructure and hypervisor, and the customer manages the OS, applications, and data. In SaaS, the provider handles far more of the stack.'),
  (409, 'secplus-risk-management', 'A metric showing a rising number of unpatched critical vulnerabilities is used to warn of increasing risk. What is this metric called?', 'A service level agreement', 'A recovery point objective', 'An exposure factor', 'A key risk indicator (KRI)', 'D', 'KRIs are early warning signals that risk is changing. They help management act before an incident happens.'),
  (410, 'secplus-data-protection', 'A company blocks access to its cloud application from countries where it doesn''t do business. Which data protection method is this?', 'Geographic restrictions', 'Steganography', 'Hashing', 'Tokenization', 'A', 'Geographic restrictions, or geofencing, limit access by location. They help enforce data sovereignty and reduce exposure.'),
  (411, 'secplus-hardening', 'What is a secure baseline?', 'The minimum hardware required to run an OS', 'The first full backup taken of a system', 'An approved set of secure configurations systems must meet', 'A record of normal network traffic volumes used to spot anomalies', 'C', 'A secure baseline defines the hardened starting configuration for a type of system. Systems are deployed to it and checked against it for drift.'),
  (412, 'secplus-incident-response', 'A company is notified of a lawsuit and must preserve all related emails and documents. What is this requirement called?', 'E-discovery deletion', 'A legal hold', 'Data masking', 'Tokenization', 'B', 'A legal hold suspends normal deletion so relevant data is kept. Destroying it could bring legal penalties.'),
  (413, 'secplus-security-concepts', 'Which control best prevents tailgating into a secure area?', 'Bollards at the entrance', 'Bright exterior lighting', 'An access control vestibule', 'Video surveillance cameras', 'C', 'A vestibule lets only one authenticated person through at a time, which stops tailgating. Cameras may record tailgating, but they don''t prevent it.'),
  (414, 'secplus-identity-access', 'Two companies allow each other''s employees to use their home credentials to access shared partner portals. What is this?', 'Password vaulting', 'Federation', 'Discretionary access control', 'Attestation', 'B', 'Federation establishes trust between separate organizations'' identity systems. Users authenticate with their home organization.'),
  (415, 'secplus-change-management', 'A new application must be added to the endpoint allow list before it can run. What does this mean for the change process?', 'The deny list must be updated instead of the allow list', 'Allow-listed applications are exempt from change review', 'The application is added to the allow list automatically on install', 'The allow list update must be included in the approved change', 'D', 'With application allow listing, anything not explicitly permitted is blocked, so the change must include updating the list. Allow lists never update themselves automatically.'),
  (416, 'secplus-investigation-data', 'Windows Security event logs record successful and failed logons. Which category of log is this?', 'Firewall logs', 'Application logs', 'Network logs', 'OS-specific security logs', 'D', 'Operating system security logs track authentication, privilege use, and policy changes. They''re key for investigating account misuse.'),
  (417, 'secplus-resilience-recovery', 'Why is it important to regularly test restoring from backups?', 'To remove the need to keep copies of backups at an offsite location', 'To encrypt backups after they''re made', 'To verify backups work and meet recovery goals', 'To reduce the size of future backups', 'C', 'Untested backups may be corrupt, incomplete, or too slow to restore. Regular restore tests prove recovery is possible.'),
  (418, 'secplus-enterprise-security', 'Windows administrators enforce password policies and disable USB storage across all domain computers from one place. What do they use?', 'SNMP', 'SELinux', 'Group Policy', 'NetFlow', 'C', 'Group Policy centrally configures settings on Windows domain computers. SELinux provides mandatory access control on Linux.'),
  (419, 'secplus-malicious-activity', 'Software that secretly monitors a user''s browsing and collects personal information to send to a third party is called:', 'Spyware', 'A worm', 'Ransomware', 'A logic bomb', 'A', 'Spyware gathers information without consent. It''s often bundled with free software or delivered by trojans.'),
  (420, 'secplus-secure-infrastructure', 'What distinguishes a next-generation firewall (NGFW) from a traditional stateful firewall?', 'Tracking connection state so return traffic for TCP sessions is allowed', 'Operating only at layer 2 of the OSI model', 'Application awareness, with built-in IPS and deep packet inspection', 'Filtering based only on source and destination IP', 'C', 'NGFWs add application awareness, user identity, and intrusion prevention to stateful filtering. A traditional firewall decides based on ports and addresses.'),
  (421, 'secplus-threat-actors', 'Malware quietly copies large volumes of sensitive files to an external server over several weeks. Which motivation does this most directly indicate?', 'Disruption or chaos', 'Data exfiltration', 'Service disruption', 'Ethical hacking', 'B', 'Data exfiltration is the unauthorized transfer of data out of an organization. Service disruption would make systems unavailable rather than quietly copying data.'),
  (422, 'secplus-mitigations', 'Which of the following is a host hardening technique?', 'Disabling unnecessary services and ports', 'Installing more browser toolbars', 'Increasing the screen resolution', 'Enabling guest accounts', 'A', 'Removing unneeded services shrinks the attack surface. Guest accounts and extra software add risk.'),
  (423, 'secplus-vulnerability-management', 'Two vulnerabilities have the same CVSS score, but one affects an internet-facing payment server and the other an isolated test system. How should they be prioritized?', 'Whichever the scanner discovered first', 'The payment server first, due to exposure and business impact', 'Both equally, because their CVSS base scores are identical', 'The test system first, since it''s easier to fix', 'B', 'Base scores don''t account for context such as exposure and asset value. Environmental factors and organizational impact should guide prioritization.'),
  (424, 'secplus-monitoring', 'Why is log aggregation important for security monitoring?', 'It deletes old logs automatically to save storage space on servers', 'It enables correlation and protects logs from tampering on hosts', 'It encrypts all network traffic it collects', 'It removes the need for monitoring staff', 'B', 'Attackers often clear local logs, but logs sent to a central system survive. Correlation can reveal attacks that span multiple systems.'),
  (425, 'secplus-governance', 'A cloud payroll provider processes employee data on behalf of a company. Under privacy law, the provider is the:', 'Data owner', 'Data processor', 'Data controller', 'Data subject', 'B', 'Processors act on the controller''s instructions. Controllers remain accountable for making sure processors protect the data.'),
  (426, 'secplus-audits-assessments', 'Which practice ensures a penetration test doesn''t affect systems outside the agreed targets?', 'Skipping documentation', 'Using only unknown environment testing so testers can''t see internal systems', 'Testing every IP address on the internet', 'Defining a clear scope in the rules of engagement', 'D', 'Scope defines which systems are in and out of bounds. Testing out-of-scope systems could break laws or contracts.'),
  (427, 'secplus-cryptography', 'Why is elliptic curve cryptography (ECC) popular on mobile and IoT devices?', 'It''s a symmetric algorithm, so both sides never need to exchange keys', 'It doesn''t require public and private key pairs', 'It encrypts bulk data faster than AES', 'It gives strong security with smaller keys and less processing', 'D', 'ECC achieves security comparable to RSA with much shorter keys, which saves power and bandwidth. It''s still asymmetric, so AES remains faster for bulk data.'),
  (428, 'secplus-threat-vectors', 'Several USB drives labeled Payroll Q4 are left in a company parking lot. What threat vector does this represent?', 'Default credentials', 'Removable devices', 'Unsecure wireless networks', 'Open service ports', 'B', 'Dropping infected USB drives exploits curiosity, and plugging one in can run malware. Many organizations block or restrict removable media for this reason.'),
  (429, 'secplus-vulnerabilities', 'A company still uses TLS 1.0 with outdated cipher suites on its web servers. What category of vulnerability is this?', 'VM escape', 'Cryptographic', 'Race condition', 'Side loading', 'B', 'Weak protocols and ciphers can be broken or downgraded, exposing data in transit. Disabling old versions and weak ciphers fixes the issue.'),
  (430, 'secplus-architecture-models', 'Why are embedded systems in devices like printers and HVAC controllers a security concern?', 'They never connect to the network', 'They have limited resources and rarely get updates', 'They are designed with security first', 'They run full desktop operating systems that are hard to manage', 'B', 'Embedded systems have constrained resources and long lifespans, so security updates are rare. Segmenting them from critical networks reduces risk.'),
  (431, 'secplus-risk-management', 'Installing a firewall to reduce the likelihood of a network attack is an example of:', 'Risk transference', 'Risk avoidance', 'Risk mitigation', 'Risk acceptance', 'C', 'Mitigation applies controls to reduce likelihood or impact. The activity continues, but with less risk.'),
  (432, 'secplus-security-controls', 'What is the primary purpose of a preventive control?', 'To stop a security incident from occurring', 'To identify an incident while it is happening', 'To discourage attackers with visible warnings', 'To restore systems after an incident', 'A', 'Preventive controls block an incident before it happens, such as firewalls and locks. Discouraging attackers with warnings is deterrence, which doesn''t actually stop a determined attacker.'),
  (433, 'secplus-third-party-risk', 'During vendor selection, a procurement manager discloses that their spouse owns one of the bidding companies. What issue is being managed?', 'An SLA violation', 'A conflict of interest', 'A legal hold', 'A right-to-audit clause', 'B', 'Conflicts of interest can bias vendor selection. Disclosure and recusal protect the integrity of the process.'),
  (434, 'secplus-compliance', 'Under GDPR, what is the right to be forgotten?', 'A company''s right to delete old audit logs after a set period', 'A user''s right to browse anonymously', 'An employee''s right to skip training', 'A person''s right to request deletion of their data', 'D', 'Individuals can request erasure of their personal data in many circumstances. Organizations need processes to find and delete it.'),
  (435, 'secplus-data-protection', 'Which data classification typically has the most stringent controls in a commercial organization?', 'Restricted', 'Public', 'Unclassified', 'Internal', 'A', 'Restricted data, such as trade secrets or regulated data, could cause severe harm if disclosed, so it gets the strongest protections. Public data needs very little.'),
  (436, 'secplus-hardening', 'Which Wi-Fi feature should be disabled because its PIN method can be brute-forced?', 'Wi-Fi Protected Setup (WPS)', '802.1X', 'WPA3', 'Protected management frames', 'A', 'WPS PIN mode has a design flaw that allows brute-forcing in hours. Disabling it removes that path.'),
  (437, 'secplus-incident-response', 'Building an incident response plan, training staff, and setting up tools happen in which phase?', 'Recovery', 'Preparation', 'Lessons learned', 'Containment', 'B', 'Preparation gets people, processes, and technology ready before an incident. It makes every other phase faster.'),
  (438, 'secplus-identity-access', 'What is passwordless authentication?', 'Signing in with biometrics or security keys, not a password', 'Signing in without any verification', 'Sharing a team password in a vault', 'Using one strong password for every system instead of many', 'A', 'Passwordless uses strong factors such as FIDO2 keys or device biometrics. It removes password phishing and reuse risks.'),
  (439, 'secplus-malicious-activity', 'A standard user exploits a flaw in a service to run commands as SYSTEM. What attack is this?', 'Credential replay', 'Directory traversal', 'Privilege escalation', 'A watering hole attack', 'C', 'Privilege escalation gains higher permissions than were granted. Patching and running services with least privilege limit it.'),
  (440, 'secplus-secure-infrastructure', 'What does reducing the attack surface mean in network design?', 'Encrypting traffic between internal hosts', 'Minimizing exposed services, ports, and entry points', 'Moving all services onto a single network so they''re easier to watch', 'Adding servers to spread out the load', 'B', 'Fewer exposed entry points mean fewer opportunities for attackers. Closing unused ports and removing unneeded services are common steps.'),
  (441, 'secplus-resilience-recovery', 'What is the key difference between load balancing and clustering for high availability?', 'Clustering never provides automatic failover', 'Load balancing needs only one server to work', 'Load balancers spread requests; clusters act as one system with failover', 'Load balancing copies data between storage arrays; clustering doesn''t', 'C', 'Load balancers distribute traffic across servers. Clusters coordinate nodes that share a workload or take over for a failed node.'),
  (442, 'secplus-enterprise-security', 'A company blocks employees from resolving known malicious domains at the DNS level. What is this?', 'Port security', 'NetFlow', 'DNS filtering', 'DNSSEC', 'C', 'DNS filtering refuses to resolve known bad domains, stopping connections before they start. DNSSEC protects the integrity of DNS answers.'),
  (443, 'secplus-security-concepts', 'In zero trust, which control plane component establishes or shuts down the communication path between a subject and a resource after an access decision is made?', 'Certificate authority', 'Policy enforcement point', 'Policy administrator', 'Implicit trust zone', 'C', 'The policy administrator acts on the policy engine''s decision by telling the enforcement point to open or close the session. The enforcement point itself sits in the data plane.'),
  (444, 'secplus-asset-management', 'During procurement, why should security review a new vendor''s product before purchase?', 'To transfer liability for any future breaches over to the vendor', 'To approve the vendor''s marketing claims', 'To ensure it meets security requirements before deployment', 'To negotiate a lower price with the vendor', 'C', 'Addressing security during acquisition prevents buying products that can''t be secured. Fixing problems after deployment costs far more.'),
  (445, 'secplus-automation', 'What is technical debt in the context of automation?', 'Shortcuts and unmaintained scripts that cause future problems', 'Money owed to software vendors', 'The backlog of open help desk tickets waiting to be automated', 'The monthly cost of cloud storage', 'A', 'Quickly written automation that isn''t documented or maintained becomes technical debt. Ongoing supportability must be planned.'),
  (446, 'secplus-security-awareness', 'An employee receives a suspicious email. What is the best action, according to typical security awareness training?', 'Forward it to all coworkers as a warning', 'Delete it without telling anyone', 'Report it through the official process without clicking', 'Reply to the sender and ask whether the message is legitimate', 'C', 'Reporting lets the security team analyze and block the threat for everyone. Forwarding or replying can spread or confirm the attack.'),
  (447, 'secplus-cryptography', 'OCSP stapling improves performance and privacy by:', 'Having the client download the CA''s full revocation list on each visit', 'Having the server attach a CA-signed OCSP response in the TLS handshake', 'Letting the server vouch for its own revocation status', 'Embedding the server''s private key in its certificate', 'B', 'With stapling, the server periodically fetches its own OCSP response and hands it to clients, so browsers don''t have to query the CA. Private keys are never embedded in certificates.'),
  (448, 'secplus-threat-vectors', 'Instant messages on a workplace chat app ask employees to install a security update from an external link. Which threat vector is this?', 'Removable device', 'Message-based', 'Image-based', 'Bluetooth', 'B', 'Message-based vectors include email, SMS, and instant messaging. Attackers increasingly use chat platforms because users trust them more than email.'),
  (449, 'secplus-vulnerabilities', 'What is the main characteristic of a memory injection vulnerability?', 'An app is installed from outside the official store', 'A program writes past the end of a fixed-size buffer', 'Malicious code is inserted into a running process''s memory', 'Malicious input changes the logic of a database query', 'C', 'Memory injection places code into another process''s memory space, often to evade detection. Modifying a database query through a form is SQL injection.'),
  (450, 'secplus-architecture-models', 'A company keeps sensitive databases in its own data center but runs its web front end on a public cloud. What deployment model is this?', 'Hybrid cloud', 'Private cloud only', 'Serverless only', 'Community cloud', 'A', 'A hybrid cloud combines on-premises or private infrastructure with public cloud. The connections between environments need careful security.'),
  (451, 'secplus-risk-management', 'What does the annualized rate of occurrence (ARO) represent?', 'How many times a risk is expected to occur in a year', 'The value of the asset', 'The time to restore a system', 'The percentage of an asset''s value that is lost in each incident', 'A', 'ARO estimates yearly frequency, so once every 10 years is 0.1. It''s multiplied by SLE to get ALE.'),
  (452, 'secplus-threat-actors', 'A marketing team signs up for an unapproved cloud file-sharing service to work around slow IT processes. This is an example of:', 'Shadow IT', 'A nation-state threat', 'A logic bomb', 'Hacktivism', 'A', 'Shadow IT is technology used without the IT department''s knowledge or approval. It usually isn''t malicious, but it creates unmanaged risk and data exposure.'),
  (453, 'secplus-mitigations', 'An organization uses a tool that automatically checks servers against a secure baseline and fixes settings that drift. What is this?', 'Data masking', 'Tokenization', 'Configuration enforcement', 'Penetration testing', 'C', 'Configuration enforcement keeps systems aligned with approved baselines and corrects drift. It prevents insecure changes from lingering unnoticed.'),
  (454, 'secplus-vulnerability-management', 'What is the exposure factor in vulnerability and risk analysis?', 'The percentage of asset value lost per incident', 'The CVSS base score of a vulnerability', 'The number of times a threat occurs per year', 'The number of exposed ports on a system', 'A', 'Exposure factor estimates the share of value lost in an incident. It''s used to calculate single loss expectancy (SLE = asset value x EF).'),
  (455, 'secplus-monitoring', 'What should happen after an alert is investigated and remediated?', 'Ignore similar alerts from that host', 'Permanently disable the alert rule', 'Validate the fix and document the outcome', 'Delete the alert record', 'C', 'Validation confirms the threat was removed, and documentation supports future investigations and tuning. Disabling rules could hide future attacks.'),
  (456, 'secplus-governance', 'Which policy defines how employees may use company computers, email, and internet access?', 'Business continuity policy', 'Change management policy', 'Acceptable use policy', 'Data retention policy', 'C', 'An AUP sets the rules of appropriate use and the consequences of misuse. Employees typically sign it during onboarding.'),
  (457, 'secplus-audits-assessments', 'What is the role of an audit committee?', 'To perform penetration tests on critical systems', 'To oversee internal audit and ensure findings are fixed', 'To approve each individual change request', 'To configure and tune the security tools', 'B', 'Audit committees, usually part of the board, provide independent oversight of audits and controls. They help ensure accountability.'),
  (458, 'secplus-identity-access', 'Which protocol is used to query and modify directory services such as Active Directory?', 'OAuth', 'SAML', 'LDAP', 'SNMP', 'C', 'The Lightweight Directory Access Protocol reads and writes directory information. LDAPS adds TLS encryption.'),
  (459, 'secplus-change-management', 'Who is typically accountable for a system affected by a proposed change and must approve it?', 'The system owner', 'The vendor''s sales representative', 'The newest member of the IT team', 'An external auditor', 'A', 'Ownership is a key part of change management: the system owner is accountable for the asset and must accept the change''s risk. Auditors review the process but don''t approve individual changes.'),
  (460, 'secplus-malicious-activity', 'An attacker repeatedly sends deauthentication frames to disconnect clients from a wireless network. What is the most likely goal?', 'To downgrade clients from WPA3 to WEP encryption', 'To push a firmware update to client devices', 'To force reconnections to capture handshakes or lure clients to an evil twin', 'To jam the frequency so that no wireless signal can be used by anyone nearby', 'C', 'Deauthentication attacks disrupt Wi-Fi and are often a setup for capturing handshakes or an evil twin. WPA3 and 802.11w protected management frames resist them.'),
  (461, 'secplus-secure-infrastructure', 'A remote worker connects to the office network through an encrypted tunnel over the internet. What technology is this?', 'A screened subnet', 'SD-WAN', 'A remote access VPN', 'A site-to-site VPN', 'C', 'A remote access VPN connects individual users to the corporate network. A site-to-site VPN connects whole networks, such as two offices.'),
  (462, 'secplus-data-protection', 'Patient health information protected by HIPAA is an example of which data type?', 'Regulated data', 'Public data', 'Non-human-readable data', 'Intellectual property', 'A', 'Regulated data is governed by laws such as HIPAA, GDPR, or PCI DSS. Mishandling it can bring legal penalties.'),
  (463, 'secplus-hardening', 'Which wireless security protocol replaces the pre-shared key handshake with Simultaneous Authentication of Equals (SAE) to resist offline dictionary attacks?', 'WPA2-Personal', 'WPS', 'WPA3', 'WEP', 'C', 'WPA3-Personal uses SAE, which prevents attackers from capturing a handshake and cracking the password offline. WPA2-Personal''s four-way handshake is vulnerable to that.'),
  (464, 'secplus-incident-response', 'What is the correct order of the incident response process?', 'Preparation, detection, analysis, eradication, containment, recovery, lessons learned', 'Detection, analysis, preparation, containment, eradication, recovery, lessons learned', 'Preparation, containment, detection, analysis, eradication, recovery, lessons learned', 'Preparation, detection, analysis, containment, eradication, recovery, lessons learned', 'D', 'Incident response starts with preparation and ends with lessons learned, which feed back into preparation. Containment must come before eradication so the threat stops spreading.'),
  (465, 'secplus-investigation-data', 'An EDR agent records that powershell.exe spawned from a Word document. Which type of log is this?', 'Vulnerability scan results', 'Network logs', 'Endpoint logs', 'Firewall logs', 'C', 'Endpoint logs capture process, file, and registry activity on a host. Office documents launching PowerShell is a common malware indicator.'),
  (466, 'secplus-resilience-recovery', 'Which device provides short-term battery power so systems can keep running or shut down cleanly during an outage?', 'A surge protector only', 'A power distribution unit without batteries', 'An uninterruptible power supply (UPS)', 'A generator', 'C', 'A UPS bridges the gap until generators start, or allows a graceful shutdown. Generators provide long-term power but take time to start.'),
  (467, 'secplus-enterprise-security', 'A system flags that an accountant downloaded 10 times more files than usual at 3 a.m. Which capability detected this?', 'Sender Policy Framework (SPF)', 'File integrity monitoring (FIM)', 'User behavior analytics (UBA)', 'Network access control (NAC)', 'C', 'UBA builds baselines of normal user behavior and flags deviations. It helps detect insider threats and compromised accounts.'),
  (468, 'secplus-security-controls', 'After a web server is compromised, administrators wipe it and restore it from a known-good backup. Which control type is being applied?', 'Preventive', 'Detective', 'Corrective', 'Deterrent', 'C', 'Corrective controls fix problems after an incident and restore normal operations. A preventive control would have stopped the compromise from happening in the first place.'),
  (469, 'secplus-third-party-risk', 'Why is ongoing vendor monitoring important after a contract is signed?', 'Contracts guarantee vendors never change', 'Vendors must be replaced every year', 'A vendor''s security posture can change over time', 'Monitoring replaces the need for due diligence before signing', 'C', 'Breaches, acquisitions, or financial trouble can change vendor risk. Periodic reassessment keeps the risk managed.'),
  (470, 'secplus-compliance', 'Who is the data subject in privacy regulations?', 'The cloud provider hosting it', 'The company storing the data', 'The person the data is about', 'The database administrator', 'C', 'Data subjects are the people whose personal information is processed. Privacy laws give them rights over that data.'),
  (471, 'secplus-cryptography', 'Diffie-Hellman is primarily used to:', 'Create digital signatures that prove a sender''s identity', 'Establish a shared secret over an untrusted network', 'Hash passwords so they can be stored securely', 'Encrypt large files stored on a server''s disk', 'B', 'Diffie-Hellman lets two parties agree on a shared secret without sending it across the network. That secret then keys a symmetric cipher for the actual data.'),
  (472, 'secplus-threat-vectors', 'A new network camera is installed with the manufacturer''s username and password unchanged. Which threat vector does this create?', 'Watering hole', 'Default credentials', 'Supply chain compromise', 'Vishing', 'B', 'Default credentials are publicly documented, so attackers can log in easily. Changing them during setup is a basic hardening step.'),
  (473, 'secplus-vulnerabilities', 'An attacker breaks out of a guest virtual machine and gains access to the hypervisor and other VMs on the host. What vulnerability was exploited?', 'Jailbreaking', 'Side loading', 'Resource reuse', 'VM escape', 'D', 'VM escape breaks the isolation between a guest and the host, which is one of the most serious virtualization risks. Keeping hypervisors patched is the main defense.'),
  (474, 'secplus-architecture-models', 'Developers upload individual functions that run only when triggered, without managing any servers. What architecture is this?', 'Microservices on bare metal', 'On-premises', 'Mainframe', 'Serverless', 'D', 'In serverless computing, the provider runs and scales the code on demand, and the customer manages no servers. Security focus shifts to code, permissions, and configuration.'),
  (475, 'secplus-risk-management', 'Management decides the cost of fixing a low-impact risk exceeds the potential loss and chooses to do nothing further. Which strategy is this?', 'Transference', 'Acceptance', 'Avoidance', 'Mitigation', 'B', 'Risk acceptance is a conscious, documented decision to live with a risk. It''s appropriate when controls cost more than the risk.'),
  (476, 'secplus-identity-access', 'When an employee leaves the company, what should happen to their accounts?', 'Keep them active for 90 days', 'Convert them to a guest account', 'Give the password to their manager', 'Promptly disable or remove their access', 'D', 'Prompt deprovisioning prevents former employees, or attackers, from using leftover access. Accounts are often disabled first, then deleted after review.'),
  (477, 'secplus-security-concepts', 'Which property, provided by digital signatures, prevents a sender from later denying they sent a message?', 'Availability', 'Confidentiality', 'Non-repudiation', 'Authorization', 'C', 'Only the sender holds the private key used to sign, so a valid signature proves they sent the message. That is non-repudiation. Encryption, not signing, provides confidentiality.'),
  (478, 'secplus-malicious-activity', 'A user''s account successfully logs in from New York, then from Singapore 20 minutes later. What indicator is this?', 'Out-of-cycle logging', 'Resource exhaustion', 'Impossible travel', 'Account lockout', 'C', 'No one can travel that distance in 20 minutes, so the credentials are likely being used by someone else. Many identity platforms flag this automatically.'),
  (479, 'secplus-secure-infrastructure', 'A firewall protecting a hospital''s patient records is configured to block all traffic if the firewall fails. What failure mode is this?', 'Fail-safe for availability', 'Fail-open', 'Fail-over', 'Fail-closed', 'D', 'Fail-closed (fail-secure) blocks traffic on failure, prioritizing security over availability. Fail-open lets traffic pass, which keeps the business running but leaves it unprotected.'),
  (480, 'secplus-threat-actors', 'Which statement about hacktivists is most accurate?', 'They seek long-term, stealthy access to steal intelligence', 'They attack mainly to extort ransom payments from victims', 'They promote a cause, often through defacement, leaks, or DDoS', 'They are funded by governments to support military goals', 'C', 'Hacktivists want visibility for their cause, so their attacks are often public. Long-term, stealthy access is more typical of nation-state espionage.'),
  (481, 'secplus-mitigations', 'A file server''s shares are set so the Finance group can modify files and everyone else can only read them. Which mitigation is this?', 'Network segmentation of the file server', 'Permissions as part of access control', 'Isolation of the Finance department', 'Configuration enforcement on the server', 'B', 'File permissions limit who can read or change data. Combined with least privilege, they reduce insider and malware damage.'),
  (482, 'secplus-vulnerability-management', 'A critical patch can''t be applied to a production system for 60 days because of a vendor dependency. What is the best interim response?', 'Disable monitoring until the patch is applied', 'Remove the system from the asset inventory until it can be patched', 'Wait for the patch without any other action', 'Apply compensating controls and document an exception', 'D', 'When patching must wait, compensating controls reduce risk, and an approved exception records the decision. Ignoring it leaves the risk unmanaged.'),
  (483, 'secplus-monitoring', 'After an alert identifies malware on a workstation, the system automatically disconnects it from the network. What action is this?', 'Enumeration', 'Archiving', 'Quarantine', 'Attestation', 'C', 'Quarantine isolates an affected system to stop spread while it''s investigated. It''s a common automated response.'),
  (484, 'secplus-governance', 'Which role performs day-to-day tasks such as backups, applying access controls, and maintaining storage for data?', 'Data subject', 'Data owner', 'Data controller', 'Data custodian (steward)', 'D', 'Custodians carry out the protections defined by the owner. They handle the technical upkeep, not the classification decisions.'),
  (485, 'secplus-audits-assessments', 'Penetration testers are given full network diagrams, source code, and credentials before testing. What type of test is this?', 'Known environment (white box)', 'Partially known environment (gray box)', 'Passive reconnaissance', 'Unknown environment (black box)', 'A', 'In a known environment test, testers have complete information, which allows thorough coverage. Unknown environment tests simulate an outside attacker with no inside information.'),
  (486, 'secplus-data-protection', 'Which classification would typically apply to internal company emails and policies that shouldn''t be shared outside but would cause limited harm if leaked?', 'Public', 'Top secret', 'Private or internal', 'Restricted', 'C', 'Internal (private) data is meant for employees only but is less sensitive than confidential or restricted data. Classification decides what handling is required.'),
  (487, 'secplus-hardening', 'Why is maintaining a secure baseline an ongoing process rather than a one-time task?', 'Baselines expire automatically each year', 'A baseline can''t be changed once applied', 'Baselines are only checked during audits', 'Systems drift, and new threats require updates', 'D', 'Patches, changes, and new threats mean baselines must be reviewed and systems rechecked regularly. Without that, configurations slowly drift out of compliance.'),
  (488, 'secplus-incident-response', 'Why should incident responders work from a forensic copy instead of the original drive?', 'Copies don''t need a chain of custody', 'The original drive is always encrypted', 'Copies are always faster', 'Analysis could alter the original evidence', 'D', 'Preserving the original keeps evidence admissible. Write blockers prevent changes during acquisition.'),
  (489, 'secplus-resilience-recovery', 'Capacity planning for resilience should consider which of the following?', 'Only the number of servers needed', 'People, technology, and infrastructure', 'Only next year''s security budget', 'Only the bandwidth of internet links', 'B', 'Capacity planning makes sure there are enough staff, systems, and infrastructure, including during a crisis. Overlooking staff is a common gap.'),
  (490, 'secplus-enterprise-security', 'Why might an organization use agent-based web filtering on laptops instead of relying only on a centralized proxy?', 'Agents don''t require updates', 'Agents cost less than any proxy', 'Central proxies can''t filter encrypted HTTPS traffic at all', 'It protects laptops even off the corporate network', 'D', 'Remote devices may bypass an on-premises proxy, while an agent enforces policy anywhere. Cloud-delivered proxies are another solution.'),
  (491, 'secplus-cryptography', 'Hiding a message inside the pixels of an image file is called:', 'Tokenization', 'Blockchain', 'Hashing', 'Steganography', 'D', 'Steganography conceals the existence of a message inside another file. It is a form of obfuscation, not encryption, so it can be paired with encryption for confidentiality.'),
  (492, 'secplus-threat-vectors', 'An employee receives a text message claiming to be from their bank, with a link to verify their account. What is this attack?', 'Vishing', 'Whaling', 'Smishing', 'Pharming', 'C', 'Smishing is phishing over SMS text messages. Vishing uses voice calls, and whaling targets senior executives.'),
  (493, 'secplus-vulnerabilities', 'A user removes the manufacturer''s restrictions on an iPhone to install unapproved software. What is this called?', 'Jailbreaking', 'Geofencing', 'Side loading', 'Containerization', 'A', 'Jailbreaking (rooting, on Android) bypasses OS protections and the vendor''s security model. MDM can detect jailbroken devices and block them from corporate data.'),
  (494, 'secplus-architecture-models', 'Smart thermostats and cameras on a corporate network often have weak default credentials and rarely receive updates. Which category of device is this?', 'Hypervisor', 'Internet of Things (IoT)', 'Real-time operating system server', 'Mainframe', 'B', 'IoT devices are often designed for convenience over security. They should be placed on isolated network segments.'),
  (495, 'secplus-risk-management', 'What is a risk register?', 'A record of risks, ratings, owners, and responses', 'A log of firewall rule changes', 'A list of all employees and the systems each of them can access', 'A schedule of backup jobs', 'A', 'The risk register is the central record for managing risks over time. It assigns owners and tracks mitigation status.'),
  (496, 'secplus-identity-access', 'Over several job changes, an employee keeps accumulating permissions from each old role. What is this problem called?', 'Permission creep', 'Least privilege', 'Separation of duties', 'Federation', 'A', 'Permission creep happens when old access isn''t removed. Regular access reviews and role-based provisioning prevent it.'),
  (497, 'secplus-malicious-activity', 'Malware spreads by attaching itself to legitimate programs and needs a user to run the infected program to spread. What is it?', 'A rootkit', 'A trojan', 'A worm', 'A virus', 'D', 'A virus attaches to a host file and spreads when that file runs. A worm spreads by itself without user action.'),
  (498, 'secplus-secure-infrastructure', 'A single appliance provides firewall, antivirus, content filtering, and VPN for a small office. What is it called?', 'A jump server (bastion host)', 'A next-generation network tap', 'Unified threat management (UTM)', 'A layer 7 load balancer', 'C', 'UTM combines many security functions in one device, which simplifies management for smaller sites. The tradeoff is a single point of failure.'),
  (499, 'secplus-asset-management', 'A company uses a scanning tool to discover every device connected to its network. What is this activity called?', 'Attestation', 'Enumeration', 'Tokenization', 'Sanitization', 'B', 'Enumeration discovers and lists assets, which helps find unauthorized or unknown devices. It keeps the inventory accurate.'),
  (500, 'secplus-automation', 'What is a major risk of relying heavily on automation and orchestration?', 'Automation prevents systems from scaling', 'A flaw in automation can affect many systems at once', 'Automation always weakens security', 'Automation can''t integrate with the APIs of most security tools', 'B', 'Automation magnifies mistakes: one bad script can misconfigure everything. It also adds complexity and needs ongoing support.'),
  (501, 'secplus-security-awareness', 'Situational awareness training teaches employees to:', 'Ignore events that seem unusual', 'Notice tailgaters or people watching screens', 'Share passwords with trusted coworkers', 'Disable security tools when they slow work', 'B', 'Being alert to physical and social cues helps prevent tailgating and shoulder surfing. Employees become an extra layer of defense.'),
  (502, 'secplus-change-management', 'Before approving a firewall upgrade, the change advisory board asks how the team will return to the previous state if the upgrade fails. Which document answers this?', 'Maintenance window schedule', 'Asset inventory', 'Backout plan', 'Acceptable use policy', 'C', 'A backout plan describes how to roll back a change that fails. The maintenance window says when the change happens, not how to undo it.'),
  (503, 'secplus-investigation-data', 'How can vulnerability scan results support an investigation?', 'They reveal the attacker''s identity and source IP address', 'They contain the attacker''s packet payloads', 'They replace firewall logs', 'They show weaknesses an attacker might have exploited', 'D', 'Scan results help investigators find the likely entry point. They also show whether other systems share the same weakness.'),
  (504, 'secplus-security-controls', 'Which control category describes measures carried out primarily by people, such as awareness training and following configuration procedures?', 'Managerial', 'Physical', 'Technical', 'Operational', 'D', 'Operational controls are implemented by people in day-to-day activities. Managerial controls set direction through policy and risk management, while technical controls are enforced by systems.'),
  (505, 'secplus-third-party-risk', 'What is the purpose of a vendor security questionnaire?', 'To gather information about a vendor''s security practices', 'To test employees'' security awareness', 'To replace the need for a signed contract with the vendor', 'To advertise the company''s products', 'A', 'Questionnaires assess third-party risk in a standard way. Answers should be verified where possible, for example with audit reports.'),
  (506, 'secplus-compliance', 'A professional licensing board revokes a company''s license to operate after severe regulatory violations. What consequence is this?', 'Contractual bonus', 'Attestation', 'Due diligence', 'Loss of license', 'D', 'Some regulated industries require licenses that can be revoked for noncompliance. That can effectively shut down the business.'),
  (507, 'secplus-security-concepts', 'In a zero trust architecture, which component decides whether to grant a subject access to a resource?', 'Subject', 'Policy engine', 'Implicit trust zone', 'Policy enforcement point', 'B', 'The policy engine evaluates policy and context to make the access decision. The policy enforcement point carries out that decision in the data plane but doesn''t make it.'),
  (508, 'secplus-threat-actors', 'Attackers steal customer records and threaten to publish them unless the company pays. Which motivation does this represent?', 'Philosophical beliefs', 'Service disruption', 'Blackmail', 'Espionage', 'C', 'Threatening to release stolen data unless paid is blackmail or extortion. Espionage aims to gather intelligence quietly, without the victim knowing.'),
  (509, 'secplus-mitigations', 'Why are access control lists (ACLs) on routers and firewalls considered a mitigation technique?', 'They scan files in transit for malware', 'They encrypt all traffic that passes between connected sites', 'They restrict which traffic can pass between networks', 'They store backup copies of device configs', 'C', 'ACLs permit or deny traffic based on rules such as addresses and ports. They limit what attackers can reach.'),
  (510, 'secplus-vulnerability-management', 'Why do security teams monitor dark web forums as part of threat intelligence?', 'To host decoy sites that trap attackers', 'Because dark web sources are always reliable', 'To purchase working exploits for use in internal penetration testing', 'To find leaked credentials or planned attacks against them', 'D', 'Dark web monitoring can give early warning of breaches or targeting. Teams use specialized services instead of browsing directly.'),
  (511, 'secplus-monitoring', 'What is the main advantage of agent-based monitoring over agentless monitoring?', 'No software needs to be installed or maintained on monitored hosts', 'It works only on network infrastructure', 'It uses no system resources on the host', 'It gives deeper visibility into host processes and activity', 'D', 'Agents run on the host and see more detail. Agentless monitoring is easier to deploy but gathers less information.'),
  (512, 'secplus-governance', 'Which procedure ensures a departing employee returns equipment and has all access removed?', 'Vendor assessment', 'Offboarding', 'Onboarding', 'Change management', 'B', 'Offboarding procedures revoke access and collect assets promptly. Gaps here leave orphaned accounts attackers can use.'),
  (513, 'secplus-audits-assessments', 'Which statement best describes offensive penetration testing?', 'Monitoring logs and responding to alerts as they arrive', 'Simulating attacks to find and exploit weaknesses', 'Auditing financial records', 'Writing security policies', 'B', 'Offensive testing, red teaming, mimics attackers. Defensive work, blue teaming, focuses on detection and response.'),
  (514, 'secplus-data-protection', 'A database stores customers'' credit card numbers. Which data state applies when the data sits on the database server''s disk?', 'Data in motion', 'Data at rest', 'Data in use', 'Data in transit', 'B', 'Data at rest is stored data, protected by encryption and access controls. Data in transit moves across networks, and data in use is being processed in memory.'),
  (515, 'secplus-hardening', 'Which tool lets an organization enforce passcodes, push apps, and remotely wipe lost mobile devices?', 'A web application firewall', 'A SIEM', 'A network tap', 'Mobile device management (MDM)', 'D', 'MDM centrally manages and secures mobile devices, including remote wipe if one is lost. A SIEM collects and correlates logs.'),
  (516, 'secplus-incident-response', 'After an incident, the team meets to discuss what went well and what to improve. Which phase is this?', 'Detection', 'Eradication', 'Lessons learned', 'Containment', 'C', 'Lessons learned improves future response and prevention. Findings update plans, controls, and training.'),
  (517, 'secplus-resilience-recovery', 'Why might an organization use more than one cloud provider for critical services?', 'To reduce the number of security controls', 'To simplify management by using one console for every service', 'To remove the need for backups', 'To avoid depending on one provider''s availability', 'D', 'A multi-cloud approach reduces single-provider risk. It also adds management complexity and the need for consistent security controls.'),
  (518, 'secplus-enterprise-security', 'Which email security mechanism adds a digital signature to message headers so receivers can verify the message wasn''t altered and came from the domain?', 'POP3', 'DKIM', 'SPF', 'DMARC', 'B', 'DomainKeys Identified Mail signs messages with the domain''s private key, and receivers check it with the public key in DNS. SPF checks only the sending server.'),
  (519, 'secplus-cryptography', 'What does a blockchain''s open public ledger provide?', 'A distributed, tamper-evident record anyone can verify', 'A central record that one authority can edit', 'An encrypted record that hides all transactions', 'A private record that only miners can read', 'A', 'Each block includes the hash of the previous block, and copies are distributed, so altering past records is detectable. The ledger is public, not hidden.'),
  (520, 'secplus-threat-vectors', 'An attacker calls the help desk pretending to be an executive who is locked out and urgently needs a password reset. Which technique is being used?', 'Typosquatting a support portal', 'Vishing combined with impersonation', 'Smishing with a spoofed number', 'A watering hole attack', 'B', 'Vishing is voice phishing, and claiming to be an executive is impersonation. The urgency is a common pressure tactic to bypass verification steps.'),
  (521, 'secplus-vulnerabilities', 'A network switch is past its end-of-life date, and the vendor will no longer release firmware updates. What is the primary risk?', 'New vulnerabilities will never be patched', 'The switch will lose its configuration', 'The switch will immediately stop forwarding traffic', 'Encryption on the switch is automatically disabled', 'A', 'End-of-life hardware receives no security updates, so any newly discovered flaw stays exploitable. The device keeps working, which is why the risk is often overlooked.'),
  (522, 'secplus-architecture-models', 'What is the main security difference between containers and virtual machines?', 'Containers share the host''s kernel, so isolation is weaker', 'Virtual machines share the host''s kernel directly', 'Containers can''t run on a hypervisor host', 'Containers each run a complete guest operating system on top of the host', 'A', 'Containers are lighter because they share the host kernel, but that means weaker isolation than VMs, which have their own OS. Keeping the host kernel patched is critical.'),
  (523, 'secplus-risk-management', 'An organization''s leadership is willing to take significant risks to pursue rapid growth. Which risk appetite is this?', 'Avoidant', 'Expansionary', 'Neutral', 'Conservative', 'B', 'An expansionary appetite accepts more risk for potential reward. A conservative appetite favors safety over growth.'),
  (524, 'secplus-identity-access', 'Which practice best reflects current password guidance?', 'Complex passwords that are forced to change every 30 days', 'Passwords reused only on internal systems', 'Short passwords with symbols and numbers', 'Long passphrases checked against breached-password lists', 'D', 'Length beats complexity, and frequent forced changes lead to predictable passwords. Blocking known-breached passwords stops easy guesses.'),
  (525, 'secplus-malicious-activity', 'A disgruntled developer adds code that deletes the payroll database if their account is ever disabled. What is this?', 'A worm', 'A logic bomb', 'A rootkit', 'Spyware', 'B', 'A logic bomb sits dormant until a specific condition or date triggers it. Code reviews and separation of duties help catch it.'),
  (526, 'secplus-secure-infrastructure', 'Network sensors placed at key points in the network primarily:', 'Block any traffic that violates firewall rules between segments', 'Collect traffic data for monitoring and detection', 'Assign VLANs to devices as they connect', 'Encrypt traffic between network segments', 'B', 'Sensors gather data for IDS and NDR tools and the SIEM. Where they are placed decides which traffic can be seen.')
) as v (seq, slug, question, a, b, c, d, correct, explanation)
join public.praxis_categories c on c.slug = v.slug;
